const HTML = "<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>KOMY · 토론장</title><style>\r\n:root{--bg:#f5f6f8;--ink:#202a3b;--sub:#6b7587;--line:#e6e9ee;--blue:#385de5;--nav:#172436}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,'Malgun Gothic',sans-serif;font-size:14px}button,input,textarea,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,a:focus-visible{outline:3px solid #99afff;outline-offset:3px}.shell{display:grid;grid-template-columns:224px 1fr;min-height:100vh}aside{background:var(--nav);color:#c5cedd;padding:30px 20px;display:flex;flex-direction:column;gap:30px}.brand{color:white;font-weight:800;font-size:24px;letter-spacing:2px}.brand small{display:block;font-weight:400;font-size:10px;letter-spacing:2.5px;margin-top:9px;color:#96a5bb}.project{padding:18px 12px;border:1px solid #39465a;border-radius:10px;font-size:13px;line-height:1.8}.project span{display:block;font-size:10px;color:#98a9be;letter-spacing:1px}nav{display:grid;gap:7px}nav button{border:0;background:none;color:#aebbd0;padding:13px 14px;text-align:left;border-radius:8px}nav button.active{background:#30435e;color:#fff}.sidefoot{margin-top:auto;font-size:12px;line-height:1.9;color:#99a9bf}.online{display:inline-block;width:7px;height:7px;border-radius:50%;background:#d4a34d;margin-right:7px}main{min-width:0}.topbar{padding:20px 38px;background:#fff;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;font-size:12px;color:var(--sub)}.avatar{display:inline-grid;place-items:center;border-radius:50%;background:#edf0fc;width:29px;height:29px;color:var(--blue);margin-right:8px;font-weight:bold}.content{max-width:1450px;margin:auto;padding:36px 38px}.eyebrow{font-size:11px;color:var(--blue);font-weight:700;letter-spacing:2px}h1{font-size:29px;margin:9px 0 10px;letter-spacing:-1px}h2{font-size:17px;margin:0}h3{font-size:15px;margin:0 0 10px}p{line-height:1.8}.muted{color:var(--sub)}.hero{display:flex;justify-content:space-between;gap:20px;align-items:center}.button{border:1px solid var(--line);border-radius:7px;padding:10px 15px;background:white;color:var(--ink);font-weight:600}.primary{background:var(--blue);border-color:var(--blue);color:#fff}.small{font-size:12px;padding:8px 12px}.notice{background:#fff9ec;border:1px solid #eedeb8;color:#86632b;padding:13px 17px;border-radius:8px;font-size:12px;line-height:1.8;margin:23px 0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:22px 0}.stat{background:#fff;border:1px solid var(--line);border-radius:10px;padding:19px 22px;display:flex;justify-content:space-between;align-items:center}.stat strong{font-size:28px;letter-spacing:-1px}.stat span{color:var(--sub);font-size:12px}.workspace{display:grid;grid-template-columns:minmax(240px,310px) minmax(0,1fr);gap:20px}.card{background:#fff;border:1px solid var(--line);border-radius:11px;overflow:hidden}.cardhead{padding:22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:10px}.topic{display:block;width:100%;border:0;border-bottom:1px solid var(--line);background:#fff;text-align:left;padding:19px 22px;color:var(--ink)}.topic:hover{background:#f8f9ff}.topic.selected{background:#f0f3ff;border-left:3px solid var(--blue);padding-left:19px}.topic strong{display:block;margin:9px 0;font-size:14px;line-height:1.5}.topic small{color:var(--sub);font-size:11px}.badge{font-size:10px;border-radius:4px;padding:4px 7px;display:inline-block;background:#edf1ff;color:#526bc7}.badge.green{background:#e9f5ed;color:#35774c}.badge.amber{background:#fff3dd;color:#9b7127}.detailhead{padding:27px 28px;border-bottom:1px solid var(--line)}.detailhead h2{font-size:22px;line-height:1.5;margin:12px 0}.detailbody{padding:25px 28px}.label{font-size:11px;font-weight:bold;letter-spacing:1px;color:var(--sub);margin-bottom:10px}.proposal{background:#f7f8fb;border:1px solid var(--line);border-radius:8px;padding:17px 20px;line-height:1.9;white-space:pre-wrap}.entry{padding:20px 0;border-bottom:1px solid var(--line)}.entrytop{display:flex;justify-content:space-between;font-size:12px;gap:10px}.entrytop strong{color:var(--blue)}.entry p{white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0 0}.empty{padding:25px 12px;text-align:center;color:var(--sub);line-height:1.9;font-size:13px}.compose{margin-top:24px}textarea,input,select{border:1px solid #dce1e9;border-radius:7px;padding:12px;background:#fff;color:var(--ink);max-width:100%}textarea{width:100%;min-height:105px;resize:vertical;line-height:1.8}textarea:focus,input:focus{outline:2px solid #d4ddff;border-color:#7e96f4}.row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:11px}.row .push{margin-left:auto}.divider{height:1px;background:var(--line);margin:25px 0}.section{padding:26px}.section+.section{border-top:1px solid var(--line)}.decision{padding:18px;border-left:3px solid #3f8a61;background:#f1f8f3;margin-bottom:16px;white-space:pre-wrap;line-height:1.8}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:24px 0}.step{padding:22px;background:white;border:1px solid var(--line);border-radius:9px}.step b{display:block;color:var(--blue);font-size:11px;margin-bottom:10px}.step p{font-size:12px;color:var(--sub);margin-bottom:0}dialog{border:0;padding:28px;border-radius:13px;max-width:620px;width:calc(100% - 35px);box-shadow:0 24px 90px #15243a40}dialog::backdrop{background:#16233b70}dialog h2{margin-bottom:20px}dialog input{width:100%;margin-bottom:13px}#toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:var(--nav);color:white;padding:14px 22px;border-radius:8px;max-width:90%;z-index:10;display:none}.error{color:#ac403a}.sync{font-size:11px}.hidden{display:none!important}@media(min-width:1500px){.content{padding-top:45px}}@media(max-width:1000px){.shell{grid-template-columns:180px 1fr}.content{padding:25px}.topbar{padding:18px 25px}.workspace{grid-template-columns:240px 1fr}.detailbody,.detailhead{padding:20px}.steps{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.shell{display:block}aside{padding:16px 20px;gap:15px}.brand{font-size:19px}.brand small,.project,.sidefoot{display:none}nav{display:flex;overflow:auto;gap:3px}nav button{white-space:nowrap;padding:10px}.topbar{padding:13px 20px}.content{padding:23px 17px}.hero{align-items:flex-start}h1{font-size:24px}.stats{gap:8px}.stat{padding:14px 10px;display:block}.stat strong{display:block;margin-top:8px}.workspace{grid-template-columns:1fr}.topic{padding:12px 16px}.topic strong{margin:6px 0}.topic.selected{padding-left:13px}.cardhead{padding:17px}.steps{gap:8px}.step{padding:16px}.hero>.button{font-size:11px;padding:10px}.detailhead h2{font-size:19px}}\r\n</style><style>\r\n/* Discussion timeline: readable content, clear state and compact history. */\r\n.workspace{grid-template-columns:290px minmax(0,1fr);align-items:start}.workspace>.card{min-width:0}.detailbody{padding:24px!important}.discussion-stream{display:grid;gap:24px}.latest-discussion{border:2px solid #7287ee;border-radius:16px;overflow:hidden;background:#fff;box-shadow:0 8px 28px #2638610c}.latest-label{background:#edf1ff;color:#354bb1;font-size:12px;font-weight:800;letter-spacing:.08em;padding:13px 20px}.run-card{border:0!important;padding:22px!important;margin:0!important}.run-card>.entrytop{gap:12px;align-items:center;flex-wrap:wrap}.run-card>.entrytop strong{font-size:16px;color:#253c86}.run-card[data-status=review_required]>.entrytop strong,.run-card[data-status=failed]>.entrytop strong{color:#986018}.run-card[data-status=awaiting_approval]>.entrytop strong{color:#086b55}.run-date{font-size:12px}.brief-card,.decision-card{background:#f1f5ff;color:#243757;border:1px solid #dce4fa;border-radius:12px;padding:20px;margin:18px 0;line-height:1.8}.decision-card{background:#eff9f6;border-color:#cce8dd}.brief-card h3,.decision-card h3{font-size:19px;color:#193a66;margin:0 0 16px}.decision-card b{display:block;color:#12624e;margin-top:18px}.brief-card .entry{padding:16px 0!important;border-color:#dce4fa}.brief-card .entry h3{font-size:16px;margin-bottom:8px}.run-card>.notice{background:#fff8eb;border-color:#f0dfb9;color:#775a2d;padding:13px 16px;font-size:13px;line-height:1.7}.run-card>details,.evidence-fold,.background-fold{border:1px solid #e3e8ef;border-radius:9px;padding:12px 14px;margin:12px 0;background:#fbfcfe}.run-card summary,.history-fold>summary,.background-fold>summary,.new-debate-controls>summary{cursor:pointer;line-height:1.7;color:#40516b}.run-card .proposal{background:#fff;border:0;color:#243348;line-height:1.85;font-size:14px;padding:14px 4px}.run-card summary small{display:block;font-size:11px;overflow-wrap:anywhere;color:#7b879a}.run-card>details:has(summary):nth-of-type(2n){border-left:3px solid #b5a2e2}.run-card .evidence-fold{font-size:12px;background:#f6f8fc}.run-card .evidence-fold summary{color:#65758e}.compose-card{background:#f0f7ff;border:1px solid #bcd5f4;border-radius:14px;padding:22px;box-shadow:0 3px 14px #345b8610}.compose-card h3{margin:0;color:#244f80;font-size:19px}.compose-tabs{display:flex;gap:8px;margin:16px 0}.compose-card form{margin:0;padding:0}.compose-card textarea{background:#fff;min-height:110px;margin:12px 0;font-size:15px;line-height:1.6}.stream-compose[hidden]{display:none!important}.history-list>h3{font-size:15px;color:#53637a;margin:0 0 12px}.history-fold{border:1px solid #e0e5ed;background:#fff;border-radius:10px;margin:10px 0;overflow:hidden}.history-fold>summary{padding:15px 18px;font-size:13px;font-weight:600;background:#f7f9fc}.history-fold[open]>summary{border-bottom:1px solid #e0e5ed}.history-fold .latest-label{display:none}.timeline-post{padding:22px;line-height:1.8}.post-sean{border-left:4px solid #279b8e}.post-decision{border-left:4px solid #5668cb}.post-text{white-space:pre-wrap;overflow-wrap:anywhere}.timeline-post time{font-size:12px;color:#748198}.new-debate-controls{margin-top:24px;padding:16px;border:1px dashed #cfd8e4;border-radius:12px;background:#fafbfd}.new-debate-controls>summary{font-weight:700}.new-debate-controls>.notice{background:#f1f4fa;border-color:#dce3ef;color:#52627b}.new-debate-controls>.eyebrow{margin-top:20px}.background-fold{font-size:13px}.workspace>.card:first-child{position:sticky;top:16px}.workspace .topic small{line-height:1.6}.run-card .button{margin-top:8px}\r\n@media(max-width:1100px){.workspace{grid-template-columns:1fr}.workspace>.card:first-child{position:static}.detailbody{padding:18px!important}}\r\n@media(max-width:600px){.run-card,.timeline-post,.compose-card{padding:16px!important}.compose-tabs{flex-wrap:wrap}.brief-card,.decision-card{padding:16px}.entrytop{display:block}.entrytop span,.entrytop time{display:block;margin-top:7px}}\r\n\r\n.run-card>details.model-reply.reply-claude{border-left:3px solid #9b7bca}.run-card>details.model-reply.reply-gpt{border-left:3px solid #5c91ce}.run-card .reply-claude>summary{color:#72519b}.run-card .reply-gpt>summary{color:#356b9f}\r\n/* v4.5: a focused work surface and a single connection settings page. */\r\n.work-page{max-width:1050px;margin:auto}.work-top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:12px 0 22px}.work-top h2{font-size:28px;margin:10px 0}.work-top p{color:#586b82}.work-tabs{display:flex;gap:8px;flex-shrink:0}.connection-overview{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0}.connection-overview>div{background:#fff;border:1px solid #dce4ed;border-radius:12px;padding:16px;display:flex;justify-content:space-between;gap:8px}.saved{color:#187653}.missing{color:#8b541d}.saved-badge{font-size:12px;border-radius:6px;padding:3px 7px;background:#edf5f0;margin-left:8px}.saved-badge.missing{background:#fff4df}.secret-field{margin:18px 0}.secret-field label{font-weight:600}.secret-row{display:flex;gap:10px;margin:8px 0}.secret-row input{flex:1;min-width:0;padding:12px;border:1px solid #cfdae8;border-radius:8px}.secret-row input[readonly]{background:#f2f6fa;color:#44546b}.secret-row input::placeholder{color:#465974;opacity:1;letter-spacing:2px}.secret-field small{color:#62748b}.setup-field{display:block;margin:16px 0}.setup-field input,.setup-field select{display:block;width:100%;margin-top:7px;padding:12px;border:1px solid #cfdae8;border-radius:8px}.setup-block{border:1px solid #e0e7f0;border-radius:12px;padding:20px;margin:18px 0;background:#fbfcfe}.setup-block h3{margin-top:0}.setup-block summary,.setup-help summary,.work-evidence summary{cursor:pointer;font-weight:600}.setup-help{margin-top:22px}.setup-help li{margin:12px 0}.work-compose{border-top:4px solid #4761ef}.work-compose textarea{width:100%;box-sizing:border-box;border:1px solid #cdd8ed;border-radius:10px;padding:15px;font-size:15px;line-height:1.8}.work-actions{display:flex;align-items:center;gap:16px;margin-top:20px;flex-wrap:wrap}.work-actions span{font-size:12px;color:#62748b}.work-feedback{padding:16px;border:1px solid #bdcfee;border-radius:10px;background:#eef4ff;color:#193b6c;line-height:1.8;margin:16px 0;overflow-wrap:anywhere}.work-feedback.error{background:#fff3ed;border-color:#edc5af;color:#793d23}.latest-work{margin-top:20px;padding:24px;background:#f7faff;border:1px solid #cfddf5;border-radius:12px}.latest-work>.eyebrow{color:#3859d8}.work-instruction,.work-report{white-space:pre-wrap;line-height:1.9;overflow-wrap:anywhere}.review-summary{background:white;border-left:4px solid #369879;border-radius:8px;padding:18px;margin:20px 0}.work-evidence{border-top:1px solid #dbe4ef;padding:14px 0;margin-top:14px}.work-evidence pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:440px;overflow:auto}.work-history{border:1px solid #e0e6ef;border-radius:10px;margin-top:12px;padding:16px;background:#fff}.work-history>summary{cursor:pointer;color:#5e7087;line-height:1.7}.work-page .section{margin-bottom:20px}.work-page .entrytop h3{margin:0}.work-page details[open]>summary{margin-bottom:14px}@media(max-width:800px){.work-top{display:block}.work-tabs{margin-top:14px}.connection-overview{grid-template-columns:1fr}.setup-block,.latest-work{padding:16px}.secret-row{gap:6px}}\r\n\r\nnav button[hidden],.hero[hidden],.stats[hidden],#notice[hidden]{display:none!important}.confirm-zone{border:2px solid #5470ed;background:#f6f8ff}.confirm-item{padding:20px 0;border-top:1px solid #d7def3}.confirm-item textarea{min-height:110px}.confirm-zone h2{margin:12px 0 18px}.decision-excerpt{padding:18px;background:#fff;border-radius:12px;border-left:4px solid #4968de;margin:16px 0}.connection-fold,.task-options{padding:14px 0;color:#566b85}.connection-fold summary,.task-options summary,.review-summary summary{cursor:pointer;font-weight:600}.record-menu{margin-bottom:20px}.work-page .work-top{margin-bottom:8px}.confirm-item .row{flex-wrap:wrap;gap:12px}\r\n\r\n.review-brief{display:grid;gap:12px;margin:16px 0}.brief-part{padding:16px 18px;border-radius:12px;background:#fff;border:1px solid #dbe3ef}.brief-part h4{margin:0 0 10px;color:#1f385c;font-size:16px}.brief-part:first-of-type{border-left:4px solid #319d7b}.brief-part:nth-of-type(2){border-left:4px solid #dfa34d}.brief-part:nth-of-type(3){border-left:4px solid #526ceb}.brief-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.85;font-size:15px}\r\n\r\n.followup-box{padding:18px;margin:18px 0;background:#eef4ff;border:1px solid #c6d7ff;border-radius:12px}.followup-box summary{cursor:pointer;font-weight:700;color:#3155b6}.followup-box textarea{min-height:110px}.followup-box button{margin-top:12px}\r\n\r\n.work-instruction-fold{display:block;clear:both;margin:18px 0!important;padding:4px 0;line-height:1.7}.work-instruction-fold>summary{display:list-item;cursor:pointer;min-height:26px;line-height:26px}.work-links{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:16px 0 22px;clear:both}.work-links .button{display:inline-flex;align-items:center;justify-content:center;min-height:42px;box-sizing:border-box;line-height:1.4;margin:0;text-decoration:none;padding:10px 16px}\r\n</style></head><body><div class=\"shell\"><aside><div class=\"brand\">KOMY<small>COUNCIL WORKSPACE</small></div><div class=\"project\"><span>CURRENT PROJECT</span>KOMY 자동 개발 환경<br><small>기획 · 설계 단계</small></div><nav aria-label=\"주 메뉴\"><button class=\"active\" data-view=\"forum\">◈　토론장</button><button data-view=\"direction\">☷　프로젝트 방향</button><button data-view=\"decisions\">✓　결정 기록</button><button data-view=\"connection\">⚙　AI 연결</button></nav><div class=\"sidefoot\"><span class=\"online\"></span>AI 연결 대기<br>제안은 함께, 결정은 명확하게.<br>KOMY TRADING © 2026</div></aside><main><div class=\"topbar\"><span>작업 공간　 /　 <b id=\"breadcrumb\">토론장</b></span><span><span class=\"avatar\">S</span>사용자 · 최종 결정자</span></div><div class=\"content\"><div class=\"hero\"><div><div class=\"eyebrow\">BUILD THE PLAN, TOGETHER</div><h1>좋은 설계는, 좋은 토론에서.</h1><div class=\"muted\">프로젝트 방향을 남기고, 쟁점을 검토하고, 중요한 결정을 확정해.</div></div><button class=\"button\" id=\"export\">↗ 기획서 내보내기</button></div><div id=\"notice\" class=\"notice\">AI 자동 토론은 아직 연결 전입니다. 아래는 기존 대화를 정리한 초기 안건이며, 새로운 AI 발언이 아닙니다. 입력한 기록은 서버에 저장돼.</div><div class=\"stats\"><div class=\"stat\"><span>검토할 안건</span><strong id=\"nOpen\">—</strong></div><div class=\"stat\"><span>승인한 결정</span><strong id=\"nDone\">—</strong></div><div class=\"stat\"><span>보류 중인 안건</span><strong id=\"nHeld\">—</strong></div></div><div id=\"view\"></div><p id=\"sync\" class=\"muted sync\" aria-live=\"polite\">기록을 불러오는 중…</p></div></main></div><dialog id=\"newTopic\"><h2>새 안건 만들기</h2><form id=\"topicForm\"><input name=\"title\" required maxlength=\"120\" placeholder=\"무엇을 논의할까?\" aria-label=\"안건 제목\"><textarea name=\"text\" required maxlength=\"12000\" placeholder=\"배경, 고민하는 선택지, 결정할 내용을 입력하십시오.\" aria-label=\"안건 내용\"></textarea><div class=\"row\"><button type=\"button\" class=\"button\" id=\"cancelTopic\">취소</button><button class=\"button primary push\">안건 등록</button></div></form></dialog><div id=\"toast\" role=\"status\"></div>\r\n<script>\r\nconst initial=[\r\n{id:'scope',title:'첫 개발 범위와 성공 기준',text:'[기존 대화에서 정리한 제안 · 미승인]\\n한 품목군의 읽기 전용 재고·출고 파일럿을 유지한다. 자동 개발 환경의 첫 실증은 가상 입고 → 예약 → 부분출고 → 취소 → 잔여재고 확인으로 한다.\\n결정할 내용: 첫 품목군, 기준 자료, 통과 조건.'},\r\n{id:'authority',title:'AI가 스스로 결정할 수 있는 범위',text:'[기존 대화에서 정리한 제안 · 미승인]\\n작업 분배·수정·가상 데이터 시험은 승인된 범위에서 자동 처리한다. 목표·예산·계산 규칙 변경과 운영 반영은 사용자 승인 대상으로 한다.\\n결정할 내용: 자동 처리 허용 목록과 강제 차단 방법.'},\r\n{id:'accuracy',title:'ERP 계산 정확성을 어떻게 검증할까',text:'[기존 대화에서 정리한 제안 · 미승인]\\n사람이 확정한 정답 사례, 독립 검산, 무작위 거래 시험, 동시 처리·장애 시험, 원거래 대사를 함께 적용한다. 금액 정밀도·반올림·배부 잔액 처리 규칙을 먼저 고정한다.\\n결정할 내용: 핵심 계산 범위와 정답 기준.'},\r\n{id:'debate',title:'토론의 순서와 종료 조건',text:'[기존 대화에서 정리한 제안 · 미승인]\\n첫 의견은 독립 작성하고, 이후 반론·수정을 두 차례 진행한다. 매니저는 확정 가능·시험 필요·사용자 결정 필요로 정리한다. AI 합의만으로 정확성을 확정하지 않는다.\\n결정할 내용: 최대 토론 횟수, 근거 형식, 의견 충돌 시 처리.'},\r\n{id:'night',title:'밤사이 작업의 한도와 중단·재개',text:'[기존 대화에서 정리한 제안 · 미승인]\\n승인된 작업 목록 안에서 시작한다. 제작 작업 하나와 별도 검증 작업 하나로 먼저 실증한다. 비용·시간·재시도 상한을 두고, 중단 후에도 작업 상태를 이어받는다.\\n결정할 내용: 실제 한도와 아침 보고 방식.'},\r\n{id:'integration',title:'Claude·GPT 연결과 기록 보존',text:'[아직 결정되지 않은 설계 안건]\\n토론장은 하나의 공동 기획서와 변경 이력을 관리해야 한다. 두 AI를 실제로 호출할 실행 경로, 인증, 사용료, 실패 처리를 확인해야 한다.\\n결정할 내용: API 또는 승인된 에이전트 실행 방식, 연결 시험, 비용 상한. 비밀키는 채팅이나 의견란에 입력하지 않는다.'}\r\n];\r\nlet activeProject='workshop',recordVersion=0;\r\nlet events=[],current='forum',selected='scope',loaded=false,busy=false;\r\nconst $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\nfunction topics(){let a=(activeProject==='workshop'?initial:[]).map(t=>({...t,status:'open',messages:[]}));for(const e of events){let p=e.payload;if(e.type==='topic')a.push({id:p.topicId,title:p.title,text:p.text,status:'open',messages:[]});else {let t=a.find(t=>t.id===p.topicId);if(t&&e.type==='message')t.messages.push(e);if(t&&e.type==='decision'){t.status=p.status==='reopened'?'open':p.status;t.decision=e;}}}return a;}\r\nconst names={sean:'사용자','import-claude':'Claude 의견 · 수동 전달','import-gpt':'GPT 의견 · 수동 전달'};\r\nconst badge=t=>`<span class=\"badge ${t.status==='approved'?'green':t.status==='held'?'amber':''}\">${{open:'검토 대기',approved:'승인 완료',held:'보류'}[t.status]}</span>`;\r\nfunction toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',4500);}\r\nasync function load(){const requestedProject=activeProject;try{const r=await fetch('/api/events?project='+encodeURIComponent(activeProject));const d=await r.json();if(!r.ok)throw Error(d.error);if(requestedProject!==activeProject)return;events=d.events;recordVersion=d.version??(events.at(-1)?.id||0);loaded=true;$('#sync').textContent='서버 기록 동기화 완료 · '+new Date().toLocaleTimeString('ko-KR');render();}catch(e){if(requestedProject!==activeProject)return;loaded=false;$('#sync').textContent=e.message;$('#sync').classList.add('error');render();}}\r\nasync function save(type,payload){if(!loaded||busy)return;busy=true;document.querySelectorAll('form button').forEach(b=>b.disabled=true);try{const r=await fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,payload:{...payload,projectId:activeProject},version:recordVersion})});const d=await r.json();if(!r.ok)throw Error(d.error);await load();toast('기록을 저장했습니다.');return true;}catch(e){toast(e.message);return false;}finally{busy=false;document.querySelectorAll('form button').forEach(b=>b.disabled=!loaded);}}\r\nfunction render(){const ts=topics();$('#nOpen').textContent=ts.filter(t=>t.status==='open').length;$('#nDone').textContent=ts.filter(t=>t.status==='approved').length;$('#nHeld').textContent=ts.filter(t=>t.status==='held').length;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===current));$('#breadcrumb').textContent={forum:'토론장',direction:'프로젝트 방향',decisions:'결정 기록',connection:'AI 연결'}[current];const disabled=!loaded||busy?'disabled':'';\r\n if(current==='forum'&&!ts.length){$('#view').innerHTML='<div class=\"card\"><div class=\"section\"><h2>아직 안건이 없어</h2><p>이 프로젝트에서 논의할 일을 등록하십시오.</p><button class=\"button primary\" id=\"add\">+ 첫 안건 등록</button></div></div>';$('#add').onclick=()=>$('#newTopic').showModal();return;}\r\n if(current==='forum'){const t=ts.find(t=>t.id===selected)||ts[0];$('#view').innerHTML=`<div class=\"workspace\"><div class=\"card\"><div class=\"cardhead\"><h2>논의할 안건 <span class=\"muted\">${ts.length}</span></h2><button class=\"button small\" id=\"add\" ${disabled}>＋ 새 안건</button></div>${ts.map((a,i)=>`<button class=\"topic ${a.id===t.id?'selected':''}\" data-topic=\"${esc(a.id)}\">${badge(a)}<strong>${String(i+1).padStart(2,'0')}　${esc(a.title)}</strong><small>의견 ${a.messages.length}개 · ${a.decision?'결정 기록 있음':'확정 전'}</small></button>`).join('')}</div><div class=\"card\"><div class=\"detailhead\"><span class=\"eyebrow\">DISCUSSION BRIEF</span><h2>${esc(t.title)}</h2>${badge(t)}</div><div class=\"detailbody\"><div class=\"label\">논의 배경과 초안</div><div class=\"proposal\">${esc(t.text)}</div><div class=\"divider\"></div><h3>의견과 검토</h3>${t.messages.length?t.messages.map(m=>`<article class=\"entry\"><div class=\"entrytop\"><strong>${esc(names[m.payload.author])}</strong><span class=\"muted\">${new Date(m.created_at).toLocaleString('ko-KR')}</span></div><p>${esc(m.payload.text)}</p></article>`).join(''):'<div class=\"empty\">아직 등록된 의견이 없습니다.<br>사용자의 조건을 남기거나, 실제 AI 답변을 전달해 기록할 수 있습니다.</div>'}<form id=\"messageForm\" class=\"compose\"><label class=\"label\" for=\"message\">의견 남기기</label><textarea id=\"message\" name=\"text\" required maxlength=\"12000\" placeholder=\"조건, 반론, 확인할 시험을 남겨 줘. 비밀키는 입력하지 마.\"></textarea><div class=\"row\"><select name=\"author\" aria-label=\"의견 출처\"><option value=\"sean\">사용자 직접 작성</option><option value=\"import-claude\">Claude 답변 수동 전달</option><option value=\"import-gpt\">GPT 답변 수동 전달</option></select><button class=\"button primary push\" ${disabled}>의견 저장</button></div></form><div class=\"divider\"></div><h3>사용자의 결정</h3>${t.decision?`<div class=\"decision\">${esc(t.decision.payload.text)}<br><small>${new Date(t.decision.created_at).toLocaleString('ko-KR')} · 사용자 기록</small></div>`:''}<form id=\"decisionForm\"><textarea name=\"text\" required maxlength=\"12000\" placeholder=\"승인할 내용과 조건, 또는 보류 이유를 입력하십시오.\"></textarea><div class=\"row\"><select name=\"status\" aria-label=\"결정 상태\"><option value=\"approved\">이 내용으로 승인</option><option value=\"held\">보류</option><option value=\"reopened\">재논의</option></select><button class=\"button push\" ${disabled}>결정 기록</button></div></form></div></div></div>`;document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{selected=b.dataset.topic;render();});$('#add').onclick=()=>$('#newTopic').showModal();$('#messageForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const ok=await save('message',{topicId:t.id,text:f.get('text').trim(),author:f.get('author')});if(ok)$('#message').value='';};$('#decisionForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await save('decision',{topicId:t.id,text:f.get('text').trim(),status:f.get('status')});};}\r\n else if(current==='direction'){const ds=events.filter(e=>e.type==='direction');$('#view').innerHTML=`<div class=\"card\"><div class=\"section\"><div class=\"eyebrow\">NORTH STAR</div><h2 style=\"margin-top:12px\">사용자가 정하는 프로젝트 방향</h2><p class=\"muted\">새 지시는 이전 지시를 삭제하지 않고 이력으로 남아. 충돌하는 조건은 후속 토론에서 명시적으로 정리해야 해.</p><div class=\"proposal\">${activeProject==='workshop'?'[기존 대화에서 정리한 방향]':'[이 프로젝트의 방향을 아래에서 등록하십시오.]'}\\n사용자는 큰틀과 중요한 결정을 맡는다. 기획 토론·제작·검증·수정은 승인된 범위에서 자동화한다. ERP의 계산 정확성을 우선하고, 첫 단계는 토론으로 실행 가능한 뼈대를 확정한다.</div><form id=\"directionForm\" class=\"compose\"><textarea name=\"text\" required maxlength=\"12000\" placeholder=\"목표, 우선순위, 반드시 지킬 조건을 남겨 줘.\"></textarea><div class=\"row\"><button class=\"button primary push\" ${disabled}>새 방향 기록</button></div></form></div><div class=\"section\"><h3>방향 변경 이력</h3>${ds.length?ds.slice().reverse().map(e=>`<article class=\"entry\"><small class=\"muted\">${new Date(e.created_at).toLocaleString('ko-KR')}</small><p>${esc(e.payload.text)}</p></article>`).join(''):'<p class=\"muted\">아직 추가 지시가 없습니다.</p>'}</div></div>`;$('#directionForm').onsubmit=async e=>{e.preventDefault();await save('direction',{text:new FormData(e.target).get('text').trim()});};}\r\n else if(current==='decisions'){const ds=events.filter(e=>e.type==='decision');$('#view').innerHTML=`<div class=\"card\"><div class=\"section\"><div class=\"eyebrow\">DECISION LOG</div><h2 style=\"margin-top:12px\">결정은 이유와 함께 남겨.</h2><p class=\"muted\">현재 상태뿐 아니라 승인·보류·재논의의 모든 기록을 보관합니다.</p>${ds.length?ds.slice().reverse().map(e=>`<article class=\"entry\"><div class=\"entrytop\"><strong>${esc(ts.find(t=>t.id===e.payload.topicId)?.title||'안건')}</strong><span>${{approved:'승인',held:'보류',reopened:'재논의'}[e.payload.status]}</span></div><p>${esc(e.payload.text)}</p><small class=\"muted\">${new Date(e.created_at).toLocaleString('ko-KR')}</small></article>`).join(''):'<div class=\"empty\">아직 확정한 결정이 없습니다.<br>토론 안건에서 결정과 이유를 남기면 여기에 모여.</div>'}</div></div>`;}\r\n else{$('#view').innerHTML=`<div class=\"card\"><div class=\"section\"><div class=\"eyebrow\">CONNECTION STATUS</div><h2 style=\"margin-top:12px\">토론장은 준비됐고, AI 연결은 다음 단계야.</h2><p class=\"muted\">지금은 안건·의견·결정을 실제로 저장할 수 있습니다. 자동 AI 발언, 야간 실행, 비용 집계는 아직 작동하지 않습니다.</p><div class=\"steps\"><div class=\"step\"><b>01 · 준비 완료</b><h3>공동 기록</h3><p>안건, 방향, 의견, 결정 이력과 기획서 내보내기.</p></div><div class=\"step\"><b>02 · 연결 필요</b><h3>AI 실행 경로</h3><p>Claude와 GPT의 승인된 호출 방식·모델·인증 확인.</p></div><div class=\"step\"><b>03 · 설정 필요</b><h3>제한과 권한</h3><p>지출 상한, 최대 공방 횟수, 중단과 재개 규칙.</p></div><div class=\"step\"><b>04 · 검증 필요</b><h3>첫 실제 토론</h3><p>안건 하나로 실제 응답·실패 처리·결론 기록 시험.</p></div></div><div class=\"notice\">API 키나 비밀번호를 의견란에 넣지 마. 연결 자격정보는 서버의 비밀값으로 별도 설정해야 해. 현재 입력 화면은 비밀키를 수집하지 않습니다.</div><button class=\"button\" id=\"gotoConnect\">연결 방식 안건으로 이동 →</button></div><div class=\"section\"><h3>자동 토론에 적용할 제안</h3><p class=\"muted\">독립 초안 → 반론과 수정 → 근거 확인 → 결론 분류 → 중요 사항 승인. 합의되지 않은 내용은 미확정으로 남기며, 실제 AI 응답을 받기 전에는 AI가 발언한 것처럼 표시하지 않습니다.</p></div></div>`;$('#gotoConnect').onclick=()=>{current='forum';selected='integration';render();};}}\r\ndocument.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{current=b.dataset.view;render();});$('#cancelTopic').onclick=()=>$('#newTopic').close();$('#topicForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),id=crypto.randomUUID();if(await save('topic',{topicId:id,title:f.get('title').trim(),text:f.get('text').trim()})){selected=id;$('#newTopic').close();e.target.reset();render();}};\r\n$('#export').onclick=()=>{if(!loaded){toast('기록을 불러온 후 내보낼 수 있어.');return;}const ts=topics();const lines=['# KOMY 자동 개발 작업환경 · 공동 기획 기록','',new Date().toLocaleString('ko-KR'),'','> AI 자동 토론 연결 전. 초기 안건은 기존 대화 요약이며 새로운 AI 발언이 아님.',''];for(const e of events.filter(e=>e.type==='direction'))lines.push('## 사용자 방향',e.payload.text,'');for(const t of ts){lines.push('## '+t.title,'상태: '+{open:'미확정',approved:'승인',held:'보류'}[t.status],'',t.text,'');for(const m of t.messages)lines.push('### '+names[m.payload.author],m.payload.text,'');if(t.decision)lines.push('### 최신 결정',t.decision.payload.text,'');}lines.push('## 전체 결정 이력');for(const e of events.filter(e=>e.type==='decision'))lines.push(e.created_at+' | '+e.payload.topicId+' | '+e.payload.status,e.payload.text,'');const u=URL.createObjectURL(new Blob([lines.join('\\n')],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='KOMY_Council_Plan.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};\r\nrender();load();\r\n</script><script>// Extract labelled passages, without generating or inferring an approval.\r\nfunction reviewBrief(value){\r\n const text=String(value||'').replace(/\\r\\n/g,'\\n');\r\n const headings=[...text.matchAll(/(?:^|\\n)\\s*(?:#{1,4}\\s*)?(?:[①②③④⑤]|[1-5][.)])?\\s*(?:\\*\\*)?(완료한 일|남은 문제|사용자 결정 사항|오빠가 결정할 것|오빠가 볼 핵심|발견한 문제와 파일·근거|시험의 빈틈|추가로 필요한 주변 코드|사람 결정 사항|근거와 한계)(?:\\*\\*)?[^\\n]*\\n/g)];\r\n const parts={};\r\n for(let i=0;i<headings.length;i++){const h=headings[i];parts[h[1]]=text.slice(h.index+h[0].length,headings[i+1]?.index??text.length).trim();}\r\n return {done:parts['완료한 일']||parts['오빠가 볼 핵심']||'',issues:parts['남은 문제']||[parts['발견한 문제와 파일·근거'],parts['시험의 빈틈']].filter(Boolean).join('\\n\\n'),decisions:parts['사용자 결정 사항']||parts['오빠가 결정할 것']||parts['사람 결정 사항']||'',legacy:!!parts['오빠가 볼 핵심'],recognized:headings.length>0};\r\n}\r\nfunction reviewBriefHTML(report){\r\n const brief=reviewBrief(report);const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;');\r\n const block=(title,text)=>'<section class=\"brief-part\"><h4>'+title+'</h4><div class=\"brief-text\">'+escape(text||'별도 정리된 항목이 없습니다. 검토 원문을 확인하십시오.')+'</div></section>';\r\n return '<div class=\"review-brief\"><p class=\"muted\">GPT 검토 원문을 항목별로 발췌한 내용입니다. 작업 및 시험 완료를 독립적으로 인증한 결과는 아닙니다.</p>'+block('완료한 일 · 검토 보고',brief.done)+block('남은 문제 · 검토 의견',brief.issues)+block('사용자 결정 사항 · 검토 의견',brief.decisions)+(brief.legacy?'<p class=\"muted\">이전 형식의 보고서입니다. 기존 결정과 중복되거나 작업 범위 외의 제안이 포함될 수 있습니다.</p>':'')+'</div>';\r\n}\r\n\nfunction normalizeSecretInput(value){\r\n if(value===undefined)return undefined;\r\n if(typeof value!=='string')throw Error('키·토큰 입력 형식을 확인하십시오.');\r\n const clean=value.trim();\r\n if(clean&&/^[*•●\\s]+$/.test(clean))throw Error('별표는 저장 상태 표시입니다. 새 키·토큰을 입력하거나 비워 두어 기존 값을 유지하십시오.');\r\n return clean;\r\n}\r\nfunction secretField(name,label,present){\r\n const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\n return '<div class=\"secret-field\"><label for=\"secret-'+esc(name)+'\">'+esc(label)+' <span class=\"saved-badge '+(present?'saved':'missing')+'\">'+(present?'저장됨':'미등록')+'</span></label><div class=\"secret-row\"><input id=\"secret-'+esc(name)+'\" type=\"password\" name=\"'+esc(name)+'\" value=\"\" autocomplete=\"new-password\" placeholder=\"'+(present?'********':'여기에 붙여넣기')+'\" '+(present?'readonly':'')+' data-secret-present=\"'+Boolean(present)+'\"><button class=\"button small\" type=\"button\" data-secret-edit=\"'+esc(name)+'\">'+(present?'변경':'입력')+'</button></div><small>'+(present?'보안상 저장된 값은 표시하지 않습니다. 변경하지 않으면 기존 값이 유지됩니다.':'해당 서비스의 키 또는 토큰을 입력하십시오.')+'</small></div>';\r\n}\r\n\nfunction orderTimeline(items){return [...items].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)||b.key.localeCompare(a.key));}\r\nfunction arrangeDiscussion(runs,topic){\r\n const body=document.querySelector('.detailbody'),panel=document.querySelector('#debatePanel');if(!body||!panel)return;\r\n const formMessage=document.querySelector('#messageForm'),formDecision=document.querySelector('#decisionForm');\r\n const background=document.createElement('details');background.className='background-fold';background.innerHTML='<summary>안건 배경과 최초 제안 보기</summary><div class=\"proposal\">'+esc(topic.text)+'</div>';\r\n const items=[];\r\n panel.querySelectorAll(':scope > .run-card').forEach((node,index)=>{const run=runs[index];if(!run)return;items.push({key:'run-'+run.id,date:run.created_at,label:'AI 토론 · '+(stateNames[run.status]||run.status),node});\r\n  const memo=node.querySelector('.decision-card'),brief=node.querySelector('.brief-card');\r\n  if(memo&&brief){const extra=document.createElement('details');extra.className='background-fold';extra.innerHTML='<summary>기본 검토 안내 보기</summary>';brief.replaceWith(extra);extra.append(brief);}\r\n  const changeInfo=[...node.children].find(child=>child.classList.contains('notice')&&child.textContent.includes('지정 수정 내역'));\r\n  if(changeInfo){const fold=document.createElement('details');fold.className='background-fold';fold.innerHTML='<summary>지정 수정 내역과 변경 전후 보기</summary>';changeInfo.replaceWith(fold);fold.append(changeInfo);}\r\n  const anchor=node.querySelector('.run-date');if(anchor){if(memo)anchor.after(memo);else if(brief)anchor.after(brief);}\r\n });\r\n for(const event of events.filter(e=>['message','decision'].includes(e.type)&&e.payload.topicId===topic.id)){\r\n  const node=document.createElement('article');node.className='timeline-post '+(event.type==='decision'?'post-decision':'post-sean');\r\n  node.innerHTML='<div class=\"entrytop\"><strong>'+esc(event.type==='decision'?'사용자 결정 · '+({approved:'승인',held:'보류',reopened:'재논의'}[event.payload.status]||event.payload.status):names[event.payload.author]||'등록 의견')+'</strong><time>'+esc(new Date(event.created_at).toLocaleString('ko-KR'))+'</time></div><p class=\"post-text\">'+esc(event.payload.text)+'</p>';\r\n  items.push({key:'event-'+event.id,date:event.created_at,label:event.type==='decision'?'사용자 결정':'등록 의견',node});\r\n }\r\n const sorted=orderTimeline(items),view=document.createElement('div');view.className='discussion-stream';\r\n if(sorted.length){const newest=document.createElement('section');newest.className='latest-discussion';newest.innerHTML='<div class=\"latest-label\">● 최신 글</div>';newest.append(sorted[0].node);view.append(newest);}\r\n else{const empty=document.createElement('p');empty.className='empty';empty.textContent='아직 토론 기록이 없습니다. 의견을 남기거나 새 토론을 시작해 줘.';view.append(empty);}\r\n const compose=document.createElement('section');compose.className='compose-card';compose.innerHTML='<h3>사용자 의견과 결정 남기기</h3><p class=\"muted\">지금 보고 있는 안건에 저장돼. 의견 저장은 AI 호출을 시작하지 않습니다.</p><div class=\"compose-tabs\"><button type=\"button\" class=\"button primary\" data-compose=\"opinion\">의견·방향 남기기</button><button type=\"button\" class=\"button\" data-compose=\"decision\">결정 기록하기</button></div>';\r\n if(formMessage){formMessage.classList.add('stream-compose');compose.append(formMessage);}\r\n if(formDecision){formDecision.classList.add('stream-compose');formDecision.hidden=true;compose.append(formDecision);}\r\n compose.querySelectorAll('[data-compose]').forEach(button=>button.onclick=()=>{const decision=button.dataset.compose==='decision';if(formMessage)formMessage.hidden=decision;if(formDecision)formDecision.hidden=!decision;compose.querySelectorAll('button[data-compose]').forEach(b=>b.classList.toggle('primary',b===button));});\r\n const taskBox=document.createElement('details');taskBox.className='background-fold';taskBox.innerHTML='<summary>이 안건을 작업장 실증에 연결</summary><p>고정 예제를 실행하거나, AI에게 제한된 재고 규칙을 작성시켜 코드로 바꾸고 리뷰·시험할 수 있습니다. 이 안건의 모든 요구를 자동 구현하는 기능은 아직 아닙니다.</p><button type=\"button\" class=\"button\" id=\"createFixtureTask\">가상 재고 실증 작업 등록 · API 호출 없음</button><p><button type=\"button\" class=\"button primary\" id=\"createAITask\">AI 재고 규칙 제작 작업 등록</button></p>';taskBox.querySelector('#createFixtureTask').onclick=()=>createFixtureTask(topic);taskBox.querySelector('#createAITask').textContent='구독 제작·자동 검토로 이동';taskBox.querySelector('#createAITask').onclick=async()=>{current='bridge';bridgeTab='work';await refreshBridge();render();};compose.append(taskBox);\r\n view.append(compose);\r\n const history=document.createElement('section');history.className='history-list';history.innerHTML='<h3>이전 기록 <span class=\"muted\">'+Math.max(sorted.length-1,0)+'</span></h3>';\r\n for(const item of sorted.slice(1)){const fold=document.createElement('details');fold.className='history-fold';const summary=document.createElement('summary');summary.textContent=new Date(item.date).toLocaleString('ko-KR')+' · '+item.label;fold.append(summary,item.node);history.append(fold);}\r\n if(sorted.length>1)view.append(history);\r\n const controls=document.createElement('details');controls.className='new-debate-controls';controls.innerHTML='<summary>새 AI 토론 시작 · 연결·자료 설정</summary>';while(panel.firstChild)controls.append(panel.firstChild);\r\n // All existing forms were moved above; remove obsolete duplicated message and decision display.\r\n body.replaceChildren(view,controls,background);\r\n}\r\n\nfunction morningBrief(run){\r\n const parse=step=>{try{return JSON.parse(run.outputs.find(o=>o.step===step)?.text||'null');}catch{return null;}};\r\n const summary=parse(4),audit=parse(5);\r\n const ready=run.status==='awaiting_approval'&&audit?.verdict==='pass';\r\n const authority=run.topic_id==='authority';\r\n return {ready,title:ready?'사용자가 결정할 차례야':'아직 승인할 단계가 아닙니다',\r\n status:run.status==='correction_draft'?'지적받은 두 항목을 수정한 초안이야. 변경 전후를 확인하고 Claude 재점검을 실행할 수 있습니다. 아직 점검 통과나 승인이 아닙니다.':ready?'AI의 정리 점검까지 완료되었습니다. 실제 개발·계산 시험 완료를 뜻하지는 않아.':run.status==='review_required'?'토론은 끝났지만 결론에 수정할 내용이 남아 있습니다. 아래 보완을 먼저 처리해야 해.':'진행 중이거나 중단된 기록입니다. 최종 결론으로 승인하지 마.',\r\n cards:authority?[\r\n {question:'AI가 어디까지 알아서 일하게 할까?',recommendation:'정해 둔 작업 안에서 코드 작성·수정·가상 데이터 시험을 맡기는 안을 권장합니다.',impact:'코드 복사와 반복 확인이 줄어들어. 업무 목표나 계산 방식까지 AI가 바꾸게 하는 승인은 아닙니다.'},\r\n {question:'무엇은 사용자 허락을 꼭 받게 할까?',recommendation:'회사에 실제 적용하기, 계산 기준 바꾸기, 지출 한도 늘리기, 권한 늘리기는 사용자가 결정하는 방안을 권장합니다.',impact:'아침에는 이런 변경 요청만 확인해. 실제 금액·수량 계산 기준과 정답 예시는 별도로 확정해야 합니다.'},\r\n {question:'처음에는 어떤 자료로 시험할까?',recommendation:'가짜 거래 자료로 작은 재고 시나리오부터 시작하는 방안을 권장합니다.',impact:'실제 회사 자료나 가린 거래 자료를 넘기는 허용은 포함하지 않습니다. 필요해지면 따로 결정해.'}\r\n ]:[], decisions:summary?.decisions||[], proposals:(summary?.proposals||[]).map(p=>p.text),\r\n issues:(audit?.issues||[]).map(i=>({problem:i.claim,reason:i.reason})),\r\n tests:summary?.tests||[],notice:'추천은 화면에서 제공하는 기본 제안이야. AI 합의나 사용자의 승인으로 기록되지 않아. 이 화면 자체는 코딩·배포·권한 변경을 실행하지 않습니다.'};\r\n}\r\n\n// Pure orchestration: testable without a browser or credentials.\r\nasync function applyConnection(values,action,{post,onStatus,onModels}){\r\n onStatus('settings','키·모델 설정을 적용하고 있어…');\r\n const saved=await post('/api/debate/settings',values);\r\n onStatus('settings',saved.saved?'설정 적용 완료 · Windows 암호화 보관 중':'설정 적용 완료 · 이번 실행 메모리에 보관 중');\r\n if(action!=='models')return saved;\r\n for(const provider of ['claude','gpt']){\r\n  const label=provider==='claude'?'Claude':'OpenAI';\r\n  onStatus(provider,label+' 모델 목록 조회 중… 최대 20초');\r\n  try{\r\n   const d=await post('/api/debate/models',{provider});\r\n   if(!Array.isArray(d.models))throw Error('서버 응답 형식이 올바르지 않아.');\r\n   onModels(provider,d.models);\r\n   onStatus(provider,d.models.length?label+' 모델 '+d.models.length+'개 불러옴. 아래 선택 상자를 확인하십시오.':label+' 목록이 비어 있어. 모델 ID 직접 입력으로 진행할 수 있습니다.');\r\n  }catch(e){onStatus(provider,label+' 조회 실패: '+e.message+' 모델 ID 직접 입력으로 진행할 수 있습니다.',true);}\r\n }\r\n return saved;\r\n}\r\n\nlet projectList=[{id:'workshop',title:'AI 작업장'}];\r\nasync function loadProjects(){try{const r=await fetch('/api/debate/projects');if(!r.ok)throw Error('프로젝트를 불러오지 못했습니다.');projectList=(await r.json()).projects;render();}catch(e){toast(e.message);}}\r\nasync function chooseProject(id){if(busy)return toast('저장 완료 후 이동하십시오.');if(!projectList.some(p=>p.id===id))return;activeProject=id;selected='';events=[];jobState={jobs:[],active:null};recordVersion=0;loaded=false;debateState={...debateState,runs:[]};current='bridge';bridgeTab='work';render();await load();await refreshDebates();await refreshBridge();render();}\r\nfunction decorateProjects(){const area=document.querySelector('aside .project');area.innerHTML='<span>PROJECT · v4.9</span><select id=\"projectSelect\" style=\"width:100%;margin:10px 0;padding:8px;color:#17283c\">'+projectList.map(p=>'<option value=\"'+esc(p.id)+'\" '+(p.id===activeProject?'selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select><button class=\"button small\" id=\"allProjects\">프로젝트 관리</button>';document.querySelector('#projectSelect').onchange=e=>chooseProject(e.target.value);document.querySelector('#allProjects').onclick=()=>{current='projects';render();};document.querySelector('.hero .muted').textContent=(projectList.find(p=>p.id===activeProject)?.title||'프로젝트')+' · 안건 및 자료를 프로젝트별로 관리합니다.';}\r\nfunction projectView(){document.querySelector('#breadcrumb').textContent='프로젝트';document.querySelector('#view').innerHTML='<div class=\"card\"><div class=\"section\"><h2>프로젝트별 작업 공간</h2><p>프로젝트별 안건과 자료를 관리합니다. AI에는 선택한 프로젝트의 자료가 전달됩니다. 무인 반복 작업 및 자동 결정 요청 등록은 지원하지 않습니다.</p>'+projectList.map(p=>'<article class=\"entry\"><h3>'+esc(p.title)+'</h3><p>'+esc(p.description||'')+'</p><p class=\"muted\">Claude: 제작·초안 역할 / GPT: 검토·관리 역할 · 실제 코드 실행 연결 전</p><button class=\"button\" data-project=\"'+esc(p.id)+'\">프로젝트 열기</button></article>').join('')+'<h3>새 프로젝트</h3><form id=\"projectForm\"><input name=\"title\" required maxlength=\"80\" placeholder=\"프로젝트 이름\" style=\"width:100%;margin:10px 0\"><textarea name=\"description\" maxlength=\"1000\" placeholder=\"목표와 다룰 업무\"></textarea><button class=\"button primary\">프로젝트 만들기</button></form></div></div>';document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>chooseProject(b.dataset.project));document.querySelector('#projectForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const r=await fetch('/api/debate/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:f.get('title'),description:f.get('description')})});const d=await r.json();if(!r.ok)return toast(d.error);await loadProjects();await chooseProject(d.id);};}\r\nloadProjects();\r\n\nconst connectionFeedback={settings:{text:'설정을 적용하거나 모델 목록을 불러오십시오.'},claude:{text:'Claude: 아직 목록을 조회하지 않았어.'},gpt:{text:'OpenAI: 아직 목록을 조회하지 않았어.'}};\r\nlet debateState={connection:{},runs:[]},debateAvailable=false,debateBusy=false;\r\nconst modelsCache={claude:[],gpt:[]},baseRender=render;\r\nconst stateNames={correction_draft:'지정 수정 초안 · 재점검 전',running:'토론 중',failed:'실패 · 재개 가능',interrupted:'중단 · 재개 가능',cancelled:'사용자 중단',awaiting_approval:'정리 점검 완료 · 승인 전',review_required:'최종 점검에서 수정 필요'};\r\ndocument.querySelector('nav').insertAdjacentHTML('beforeend','<button data-view=\"sources\">▤　기획 자료</button>');\r\ndocument.querySelector('[data-view=\"sources\"]').onclick=()=>{current='sources';render();};\r\nrender=function(){baseRender();decorateProjects();decorateDebate();};\r\nfunction documents(){const map=new Map();for(const e of events){if(e.type==='source')map.set(e.payload.sourceId,{...e.payload,revision:e.id,active:true});if(e.type==='source_toggle'&&map.has(e.payload.sourceId))map.get(e.payload.sourceId).active=e.payload.active;}return [...map.values()];}\r\nfunction simpleText(text){return esc(text).replace(/^###? (.+)$/gm,'<h3>$1</h3>').replace(/\\*\\*([^*\\n]+)\\*\\*/g,'<strong>$1</strong>');}\r\nfunction citation(refs){return '<details class=\"evidence-fold\"><summary>근거 '+(refs||[]).length+'개 보기</summary>'+(refs||[]).map(r=>`<div style=\"margin:8px 0;border-left:3px solid #b6c4ef;padding:7px 12px;font-size:12px\"><b>${esc(r.source)}</b> · ${esc(r.quote)}</div>`).join('')+'</details>';}\r\nfunction morningHTML(run){\r\n const b=morningBrief(run);\r\n const cards=b.cards.map(c=>'<article class=\"entry\"><h3>'+esc(c.question)+'</h3><p><b>GPT 기본 추천</b> · '+esc(c.recommendation)+'</p><p><b>선택하면</b> · '+esc(c.impact)+'</p></article>').join('');\r\n return '<section class=\"brief-card\" style=\"margin:20px 0\"><div class=\"eyebrow\">아침 검토 요약 · v4.5</div><h3>'+esc(b.title)+'</h3><p>'+esc(b.status)+'</p>'+cards+(b.issues.length?'<h3>AI가 먼저 보완해야 할 내용</h3>'+b.issues.map(i=>'<p><b>'+esc(i.problem)+'</b></p><details><summary>지적한 이유 보기</summary>'+esc(i.reason)+'</details>').join(''):'')+'<details><summary>이번 토론에서 나온 결정 요청 '+b.decisions.length+'개</summary>'+b.decisions.map(d=>'<p>'+esc(d)+'</p>').join('')+'</details><p><b>승인 범위</b> · 승인 시에는 허용할 작업과 한도를 입력하십시오. 한도 숫자가 없는 부분은 무제한으로 승인한 것으로 보지 않아.</p><small>'+esc(b.notice)+'</small></section>';\r\n}\r\nfunction responseHTML(o){\r\n let p;try{p=JSON.parse(o.text.trim().replace(/^```(?:json)?\\s*/,'').replace(/\\s*```$/,''));}catch{return simpleText(o.text);}\r\n if(p.observations)return p.observations.map(x=>`<p><b>${esc({agree:'동의',disagree:'반론',missing:'누락 제안'}[x.kind]||x.kind)}</b> · ${esc(x.claim)}</p>${citation(x.refs)}`).join('')+`<h3>수정 제안</h3>${esc(p.proposal)}<h3>미해결 질문</h3>${(p.openQuestions||[]).map(esc).join('\\n')}`;\r\n if(p.proposals)return [['proposals','공통 제안'],['disagreements','원문상 이견'],['missing','한쪽만 제안했거나 추가 확인할 내용'],['assumptions','미확인 가정'],['tests','필요 시험 · 미실행'],['decisions','사용자 결정 사항']].map(([k,title])=>`<h3>${title}</h3>${(p[k]||[]).length?(p[k]||[]).map(x=>typeof x==='string'?'<p>'+esc(x)+'</p>':'<p>'+esc(x.text)+'</p>'+citation(x.refs)).join(''):'없음'}`).join('');\r\n if(p.verdict)return `<h3>${p.verdict==='pass'?'요약 충실성 점검: 추가 지적 없음':'요약 충실성 점검: 수정 필요'}</h3><p class=\"muted\">AI의 원문 대조 의견이며, 업무 정확성이나 계산 검증 인증은 아닙니다.</p>${(p.issues||[]).map(i=>'<p><b>'+esc(i.claim)+'</b><br>'+esc(i.reason)+'</p>'+citation(i.refs)).join('')}`;\r\n return esc(o.text);\r\n}\r\nfunction modelSelect(provider,value){\r\n const list=modelsCache[provider],known=value&&!list.some(m=>m.id===value)?[{id:value,name:value+' · 현재 설정'}]:[];\r\n return `<select name=\"${provider==='claude'?'claudeModel':'openaiModel'}\" style=\"display:block;width:100%;margin-top:8px\"><option value=\"\">목록을 불러온 뒤 선택</option>${[...known,...list].map(m=>`<option value=\"${esc(m.id)}\" ${m.id===value?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`;\r\n}\r\nfunction decorateDebate(){\r\n if(current==='jobs')return jobsView();\r\n if(current==='projects')return projectView();\r\n if(!debateAvailable)return;\r\n document.querySelector('#notice').textContent='KOMY 토론장 v4.5 · 제작은 Claude 구독, GPT API는 필요한 코드 검토에 사용해. 구독 제작·자동 검토 메뉴에서 최초 연결해 줘. 토론 API 비용은 별도입니다.';\r\n if(current==='sources')return sourcesView();\r\n if(current==='connection')return connectionView();\r\n if(current!=='forum'||!topics().length)return;\r\n const t=topics().find(t=>t.id===selected)||topics()[0],runs=debateState.runs.filter(r=>r.topic_id===t.id),latest=runs[0],docs=documents().filter(d=>d.active);\r\n const box=document.createElement('section');box.className='section';box.id='debatePanel';\r\n box.innerHTML=`<div class=\"eyebrow\">GROUNDED COUNCIL</div><h3 style=\"margin-top:12px\">근거와 함께 토론하기</h3><p class=\"muted\">독립 초안 2회 → 원문 근거 검토 2회 → 결론 1회 → Claude의 요약 점검 1회. 새 토론은 API를 총 6회 호출합니다. 점검에서 문제가 나오면 승인 대상으로 넘기지 않아.</p><div class=\"notice\">현재 프로젝트의 선택 자료 ${docs.length}개 · 방향 지시 ${events.filter(e=>e.type==='direction').length}개. 각 실행에 자료 사본을 고정해 저장합니다. 기존 채팅의 기억은 자동 전달되지 않아.</div><details><summary>이번에 전달할 자료 확인</summary>${docs.map(d=>'<p>'+esc(d.title)+' · '+d.text.length+'자</p>').join('')}<button class=\"button small\" id=\"showSources\">자료 선택·추가</button></details><label style=\"display:block;line-height:1.8;margin-top:16px\"><input type=\"checkbox\" id=\"transmitAck\"> 이 안건·방향·의견·선택 자료를 두 회사 API에 보내고 별도 과금될 수 있음을 확인했습니다.</label><div class=\"row\"><button class=\"button primary\" id=\"debateStart\" ${!loaded||!debateState.connection.configured||debateState.connection.active||debateBusy?'disabled':''}>새 토론 시작</button><button class=\"button\" id=\"debateSettings\">AI 연결 설정</button></div>${!debateState.connection.configured?'<p class=\"muted\">AI 연결에서 키를 등록하고 모델을 선택하십시오.</p>':''}${runs.map(r=>`<article class=\"entry run-card\" data-status=\"${esc(r.status)}\"><div class=\"entrytop\"><strong>${esc(r.decision?'사용자 결정 기록 있음':r.snapshot.protocolVersion===3?(stateNames[r.status]||r.status):r.status==='awaiting_approval'?'이전 방식 토론 완료 · 승인 전':stateNames[r.status]||r.status)}</strong><span>${r.step}/${r.totalSteps||5}단계 · 시도 ${r.attempts}/${r.maxAttempts||8}</span></div><p class=\"muted run-date\">${new Date(r.created_at).toLocaleString('ko-KR')} · 기록 버전 ${r.snapshot.sourceVersion} · ${esc(r.id.slice(0,8))}</p><details><summary>이 실행의 근거 자료 · ${(r.snapshot.documents||[]).length}개</summary>${(r.snapshot.documents||[]).map((d,i)=>`<details><summary>S${i+1} · ${esc(d.title)}</summary><small>SHA256 ${esc(d.hash)}</small><div class=\"proposal\">${esc(d.text)}</div></details>`).join('')}</details>${r.error?'<div class=\"notice\">'+esc(r.error)+'</div>':''}${(r.rejections||[]).length?'<details><summary>검사에서 제외된 응답 · '+r.rejections.length+'개</summary>'+r.rejections.map(x=>'<p>'+esc(x.provider)+' · '+esc(x.error_code)+' · 완료 처리하지 않음</p><div class=\"proposal\">'+esc(x.text)+'</div>').join('')+'</details>':''}${r.snapshot.revisionParent?'<p class=\"notice\">이 기록은 기존 토론의 결론 보완·재점검 결과입니다. 앞 4단계는 원래 기록에서 이어받았습니다. 추가 호출 시도는 최대 2회입니다.</p>':''}${r.snapshot.correction?'<div class=\"notice\"><b>지정 수정 내역 · 아직 재점검 전 초안</b>'+r.snapshot.correction.changes.map(c=>'<p>'+esc(c.reason)+'</p><details><summary>변경 전후 보기</summary><p>변경 전: '+esc(c.before)+'</p><p>변경 후: '+esc(c.after||'항목 삭제')+'</p></details>').join('')+'</div>':''}${r.snapshot.correction?.reviewMemo?'<div class=\"decision-card\"><h3>사용자가 먼저 볼 내용</h3><b>수정한 오류</b>'+r.snapshot.correction.reviewMemo.fixed.map(x=>'<p>'+esc(x)+'</p>').join('')+'<b>판단이 엇갈린 부분</b>'+r.snapshot.correction.reviewMemo.pending.map(x=>'<p>'+esc(x)+'</p>').join('')+'<b>사용자 결정 제안 · 아직 미승인</b>'+r.snapshot.correction.reviewMemo.decisions.map(x=>'<p>'+esc(x)+'</p>').join('')+'<small>'+esc(r.snapshot.correction.reviewMemo.notice)+'</small></div>':''}${morningHTML(r)}${r.outputs.map(o=>`<details class=\"model-reply reply-${o.provider==='claude'?'claude':'gpt'}\" style=\"margin:14px 0\" ><summary style=\"cursor:pointer;line-height:1.8\">${esc(o.model==='local-specified-edit'?'GPT 지정 수정 · 프로그램 적용':o.provider==='claude'?'Claude':'GPT · GPT')} / ${esc(o.phase)} <small class=\"muted\">${esc(o.model)}</small></summary><div class=\"proposal\" style=\"margin-top:10px;white-space:pre-wrap\">${responseHTML(o)}</div><small class=\"muted\">${esc(o.response_id||'응답 ID 미제공')} · 입력 ${o.usage.input_tokens??'?'} / 출력 ${o.usage.output_tokens??'?'}토큰</small></details>`).join('')}${r.canCorrect&&!debateState.runs.some(x=>x.snapshot.correction?.parent===r.id)?`<button class=\"button primary\" data-correction=\"${esc(r.id)}\" ${debateState.connection.active?'disabled':''}>지적 항목 수정 초안 만들기 · API 호출 없음</button>`:''}${r.status==='running'?`<button class=\"button\" data-cancel=\"${esc(r.id)}\">중단</button>`:''}${['failed','cancelled','interrupted','correction_draft'].includes(r.status)&&r.attempts<(r.maxAttempts||8)?`<label style=\"display:block;line-height:1.9\"><input type=\"checkbox\" data-resume-ack=\"${esc(r.id)}\"> ${r.snapshot.correction?'Claude 재점검 최대 1회 호출과 추가 과금을 확인했습니다.':'미완료 호출의 중복 과금 가능성을 확인했습니다.'}</label><button class=\"button\" data-resume=\"${esc(r.id)}\" ${debateState.connection.active?'disabled':''}>${r.snapshot.correction?'수정 초안 Claude 재점검 · 최대 1회':'완료 단계 다음부터 재개'}</button>`:''}${r.status==='review_required'&&(r.snapshot.revisionRound??(r.snapshot.revisionParent?1:0))<3&&!debateState.runs.some(x=>x.snapshot.revisionParent===r.id)?`<label style=\"display:block\"><input type=\"checkbox\" data-revise-ack=\"${esc(r.id)}\"> 보완·재점검 최대 2회 추가 API 호출과 과금을 확인했습니다.</label><button class=\"button primary\" data-revise=\"${esc(r.id)}\" ${debateState.connection.active||!debateState.connection.configured?'disabled':''}>지적 반영 후 다시 점검</button>`:''}${r.status==='review_required'?'<div class=\"notice\">점검에서 문제가 발견되었습니다. 가장 최근 기록의 보완 버튼으로 남은 지적부터 이어갈 수 있어. 각 보완은 추가 2회 시도, 전체 보완은 최대 3회입니다. 자동 승인하지 않습니다.</div>':''}${r.status==='awaiting_approval'?`<div class=\"notice\">아직 사람의 승인 전입니다. 원문 인용 일치와 AI 점검은 계산·운영 시험을 대신하지 않습니다.${!r.decision&&(r.snapshot.projectVersion??r.snapshot.sourceVersion)!==(events.at(-1)?.id||0)?' 실행 후 기록이 변경됐으니 최신 자료로 다시 검토해야 해.':''}</div>`:''}</article>`).join('')}`;\r\n document.querySelector('.detailbody').prepend(box);\r\n document.querySelector('#showSources').onclick=()=>{current='sources';render();};\r\n document.querySelector('#debateSettings').onclick=()=>{current='connection';render();};\r\n document.querySelector('#debateStart').onclick=async()=>{if(!document.querySelector('#transmitAck').checked)return toast('자료 전송과 과금 안내를 확인하십시오.');if(await debatePost('/api/debate/start',{topic:{id:t.id,title:t.title,text:t.text},version:recordVersion,projectId:activeProject,acknowledged:true})){await refreshDebates();render();}};\r\n box.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{await debatePost('/api/debate/cancel',{id:b.dataset.cancel});await refreshDebates();render();});\r\n box.querySelectorAll('[data-resume]').forEach(b=>b.onclick=async()=>{if(!document.querySelector(`[data-resume-ack=\"${b.dataset.resume}\"]`).checked)return toast('재호출 안내를 확인하십시오.');await debatePost('/api/debate/resume',{id:b.dataset.resume,acknowledged:true});await refreshDebates();render();});\r\n box.querySelectorAll('[data-correction]').forEach(b=>b.onclick=async()=>{b.disabled=true;await debatePost('/api/debate/correction',{id:b.dataset.correction});await refreshDebates();render();});\r\n   box.querySelectorAll('[data-revise]').forEach(b=>b.onclick=async()=>{if(!document.querySelector('[data-revise-ack=\"'+b.dataset.revise+'\"]').checked)return toast('추가 호출 안내를 확인하십시오.');b.disabled=true;await debatePost('/api/debate/revise',{id:b.dataset.revise,acknowledged:true});await refreshDebates();render();});\r\n   if(latest?.status==='awaiting_approval'){\r\n\r\n  const form=document.querySelector('#decisionForm'),label=document.createElement('label');label.style.cssText='display:block;line-height:1.8;margin:12px 0';label.innerHTML='<input type=\"checkbox\" id=\"approveRun\"> 이 결정을 이 안건의 최신 AI 토론 결과에 연결';form.prepend(label);\r\n  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),p={topicId:t.id,text:f.get('text').trim(),status:f.get('status')};if(document.querySelector('#approveRun').checked)p.runId=latest.id;await save('decision',p);};\r\n }\r\n arrangeDiscussion(runs,t);\r\n}\r\nfunction connectionView(){\r\n const c=debateState.connection;\r\n document.querySelector('#view').innerHTML=`<div class=\"card\"><div class=\"section\"><div class=\"eyebrow\">AI CONNECTION · v4.5</div><h2 style=\"margin:12px 0\">API 연결 및 모델 설정</h2><div class=\"notice\">‘이 PC에 암호화 보관’을 선택하면 현재 Windows 사용자 계정으로 암호화해 저장합니다. 같은 PC·계정에서 다시 실행하면 복원됩니다. 평문 키를 기록·내보내기·브라우저 저장소에 사용하지 않습니다. 이 PC의 같은 사용자 권한을 가진 프로그램까지 막는 기능은 아닙니다.</div><form id=\"aiConfig\" autocomplete=\"off\"><div class=\"row\"><label style=\"flex:1\">Claude 키 · ${c.claudeKeyPresent?'등록됨':'미등록'}<input style=\"display:block;width:100%;margin-top:8px\" type=\"password\" name=\"claudeKey\" autocomplete=\"off\" maxlength=\"600\" placeholder=\"${c.claudeKeyPresent?'유지하려면 비워 두기':'키 입력'}\"></label><label style=\"flex:1\">OpenAI 키 · ${c.openaiKeyPresent?'등록됨':'미등록'}<input style=\"display:block;width:100%;margin-top:8px\" type=\"password\" name=\"openaiKey\" autocomplete=\"off\" maxlength=\"600\" placeholder=\"${c.openaiKeyPresent?'유지하려면 비워 두기':'키 입력'}\"></label></div><label style=\"display:block;margin-top:18px\"><input name=\"remember\" type=\"checkbox\" ${c.keySaved?'checked':''}> 이 PC에 암호화 보관 · 다음 실행 때 자동 복원</label><div class=\"row\"><button type=\"button\" class=\"button primary\" id=\"saveConnection\">키·선택 모델 저장</button><button type=\"button\" class=\"button\" id=\"loadModels\">키 적용 후 모델 목록 불러오기</button></div><div id=\"modelFeedback\" role=\"status\" aria-live=\"polite\" class=\"notice\">${Object.entries(connectionFeedback).map(([k,v])=>`<p id=\"feedback-${k}\" class=\"${v.error?'error':''}\">${esc(v.text)}</p>`).join('')}</div><div class=\"row\" style=\"align-items:start;margin-top:22px\"><label style=\"flex:1\">Claude 모델${modelSelect('claude',c.claudeModel)}<input name=\"claudeManual\" aria-label=\"Claude 모델 ID 직접 입력\" style=\"display:block;width:100%;margin-top:8px\" placeholder=\"직접 입력: claude-sonnet-5-5\"></label><label style=\"flex:1\">OpenAI 대화용 모델 후보${modelSelect('gpt',c.openaiModel)}<input name=\"openaiManual\" aria-label=\"OpenAI 모델 ID 직접 입력\" style=\"display:block;width:100%;margin-top:8px\" placeholder=\"직접 입력: gpt-5.4-mini\"></label></div><p class=\"muted\">모델 목록은 각 계정 API에서 가져와. 목록에 나온다고 Responses 호환성·잔액·출력 성공까지 확인된 것은 아닙니다. 목록에서 선택하거나 그 아래에 모델 ID를 직접 입력한 뒤 저장하십시오. 직접 입력값이 있으면 우선 적용됩니다.</p><p class=\"muted\">${c.configured?'토론 설정 준비됨':'키 등록과 모델 선택 필요'} · ${c.keySaved?'Windows 암호화 보관 중':'이번 실행 메모리에만 보관 중'}</p></form><label style=\"display:block\"><input id=\"forgetAck\" type=\"checkbox\"> 이 앱에 저장된 키와 현재 메모리 설정만 지우기</label><button class=\"button\" id=\"forgetKeys\" style=\"margin-top:10px\">보관 키 지우기</button></div><div class=\"section\"><h3>한도와 실행 범위</h3><p>새 토론은 6회 호출, 재개 포함 최대 9회 시도. 자동 재시도는 없습니다. 출력 상한 Claude 4,096 / OpenAI 6,000토큰. 금액 한도와는 다르므로 API 계정의 사용 한도도 설정해 줘.</p><p class=\"muted\">모델 목록 조회는 생성 요청을 전송하지 않습니다. 토론 시작·재개에는 별도 API 사용료가 발생할 수 있습니다. 코딩 실행·야간 예약·온라인 배포는 아직 연결 전입니다.</p></div></div>`;\r\n\r\n const form=document.querySelector('#aiConfig');\r\n function status(key,text,error=false){\r\n  connectionFeedback[key]={text,error};const target=document.querySelector('#feedback-'+key);if(target){target.textContent=text;target.classList.toggle('error',error);}\r\n }\r\n async function action(kind){\r\n  if(form.dataset.busy==='yes')return;\r\n  const values=Object.fromEntries(new FormData(form));values.remember=form.elements.remember.checked;\r\n  values.claudeModel=values.claudeManual.trim()||values.claudeModel;values.openaiModel=values.openaiManual.trim()||values.openaiModel;delete values.claudeManual;delete values.openaiManual;\r\n  form.dataset.busy='yes';form.querySelectorAll('button,input,select').forEach(b=>b.disabled=true);\r\n  let applied=false;\r\n  try{\r\n   await applyConnection(values,kind,{\r\n    post:async(path,body)=>{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(30000)});let data;try{data=await response.json();}catch{throw Error('서버 응답을 읽지 못했습니다. 실행 창이 켜져 있는지 확인하십시오.');}if(!response.ok)throw Error(data.error||'요청 실패');if(path.endsWith('/settings')){applied=true;form.elements.claudeKey.value='';form.elements.openaiKey.value='';}return data;},\r\n    onStatus:status,onModels:(provider,models)=>{modelsCache[provider]=models;}\r\n   });\r\n  }catch(e){status('settings',e.name==='TimeoutError'?'처리 시간이 초과되었습니다. 서버 창을 확인하십시오.':e.message,true);}\r\n  finally{\r\n   form.dataset.busy='no';form.querySelectorAll('button,input,select').forEach(b=>b.disabled=false);\r\n   if(applied){await refreshDebates();render();}\r\n  }\r\n }\r\n form.onsubmit=e=>{e.preventDefault();action('save');};\r\n document.querySelector('#saveConnection').onclick=()=>action('save');\r\n document.querySelector('#loadModels').onclick=()=>action('models');\r\n document.querySelector('#forgetKeys').onclick=async()=>{if(!document.querySelector('#forgetAck').checked)return toast('삭제할 범위를 확인하십시오.');if(await debatePost('/api/debate/forget',{})){await refreshDebates();render();toast('이 앱의 보관 키와 메모리 설정을 삭제했습니다. API 키 자체를 폐기한 것은 아닙니다.');}};\r\n}\r\nfunction sourcesView(){\r\n document.querySelector('#breadcrumb').textContent='기획 자료';\r\n document.querySelector('#view').innerHTML=`<div class=\"card\"><div class=\"section\"><div class=\"eyebrow\">SHARED CONTEXT</div><h2 style=\"margin:12px 0\">토론에 함께 넣을 자료</h2><p class=\"muted\">AI 작업장의 기본 자료 3개는 기존 대화·보고서입니다. 자료는 등록한 프로젝트에서만 토론에 전달됩니다. 승인된 정책과 동일하지 않습니다. 필요한 자료만 선택하십시오. 선택 자료 전체와 방향·의견이 시작 시점에 고정됩니다.</p>${documents().map(d=>`<article class=\"entry\"><label><input type=\"checkbox\" data-source=\"${esc(d.sourceId)}\" ${d.active?'checked':''} ${!loaded?'disabled':''}> ${esc(d.title)}</label><small class=\"muted\"> · ${d.text.length}자 · 개정 ${d.revision}</small><details><summary>원문 보기</summary><div class=\"proposal\">${esc(d.text)}</div></details></article>`).join('')}<h3 style=\"margin-top:25px\">자료 추가</h3><form id=\"sourceForm\"><input name=\"title\" required maxlength=\"160\" placeholder=\"자료 제목\" style=\"width:100%;margin-bottom:10px\"><input id=\"sourceFile\" type=\"file\" accept=\".md,.txt,.json\" aria-label=\"텍스트 자료 파일\"><p class=\"muted\">MD·TXT·JSON 텍스트만 지원해. PDF는 내용을 텍스트로 옮겨 줘. 자료당 2만 자, 토론 전체는 6만 자 제한입니다. 비밀키나 민감정보는 넣지 마.</p><textarea name=\"text\" maxlength=\"20000\" required placeholder=\"자료 내용을 붙여넣거나 파일을 선택하십시오.\"></textarea><button class=\"button primary\" style=\"margin-top:12px\" ${!loaded?'disabled':''}>자료 저장</button></form></div></div>`;\r\n document.querySelectorAll('[data-source]').forEach(c=>c.onchange=()=>save('source_toggle',{sourceId:c.dataset.source,active:c.checked}));\r\n document.querySelector('#sourceFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>100000)return toast('텍스트 파일이 너무 커.');const text=await file.text();if(text.length>20000)return toast('자료당 2만 자까지 가능합니다.');const form=document.querySelector('#sourceForm');form.elements.text.value=text;if(!form.elements.title.value)form.elements.title.value=file.name;};\r\n document.querySelector('#sourceForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await save('source',{sourceId:crypto.randomUUID(),title:f.get('title').trim(),text:f.get('text').trim()});};\r\n}\r\nasync function debatePost(path,body){if(debateBusy)return null;debateBusy=true;try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'요청 실패');return d;}catch(e){toast(e.message);return null;}finally{debateBusy=false;}}\r\nasync function refreshDebates(){const requestedProject=activeProject;try{const r=await fetch('/api/debate?project='+encodeURIComponent(activeProject));if(!r.ok)return;const data=await r.json();if(requestedProject!==activeProject)return;debateState=data;debateAvailable=true;}catch{}}\r\nconst originalExport=document.querySelector('#export').onclick;\r\ndocument.querySelector('#export').onclick=async()=>{await refreshDebates();await refreshJobs();await refreshBridge();if(!debateAvailable)return originalExport();if(!loaded)return toast('기록을 먼저 불러오십시오.');const snapshot={exportedAt:new Date().toISOString(),project:{id:activeProject,title:projectList.find(p=>p.id===activeProject)?.title},events,runs:debateState.runs,jobs:jobState.jobs,subscriptionWork:bridgeProject===activeProject?{requests:bridgeState?.requests,policy:bridgeState?.policy,spend:bridgeState?.spend}:null,notice:'원문 인용 일치·AI 요약 점검은 실제 업무 시험이나 외부 사실 검증을 대신하지 않음. 키 제외.'};const u=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='KOMY_Council_Record.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};\r\nrefreshDebates().then(()=>render());\r\nsetInterval(async()=>{const before=JSON.stringify(debateState.runs.map(r=>[r.id,r.step,r.status]));await refreshDebates();const after=JSON.stringify(debateState.runs.map(r=>[r.id,r.step,r.status]));const drafting=[...document.querySelectorAll('textarea,input:not([type=checkbox]):not([type=file])')].some(e=>e.value.trim());if(before!==after&&!drafting&&!['TEXTAREA','INPUT','SELECT'].includes(document.activeElement?.tagName))render();},2500);\r\n\nlet jobState={jobs:[],active:null};\r\ndocument.querySelector('nav').insertAdjacentHTML('beforeend','<button data-view=\"jobs\">▶　제작·시험</button>');document.querySelector('[data-view=\"jobs\"]').onclick=async()=>{current='jobs';await refreshJobs();render();};\r\nasync function refreshJobs(){const project=activeProject;try{const r=await fetch('/api/debate/jobs?project='+encodeURIComponent(project));if(r.ok&&project===activeProject)jobState=await r.json();}catch{}}\r\nasync function createFixtureTask(topic,kind='inventory_fixture'){const r=await fetch('/api/debate/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:activeProject,topicId:topic.id,title:topic.title+(kind==='ai_inventory'?' · AI 재고 규칙 제작':' · 가상 재고 실증'),kind})});const d=await r.json();if(!r.ok)return toast(d.error);current='jobs';await refreshJobs();render();}\r\nfunction jobsView(){document.querySelector('#breadcrumb').textContent='제작·시험';document.querySelector('#view').innerHTML='<div class=\"card\"><div class=\"section\"><div class=\"eyebrow\">FIRST EXECUTION · v4.5</div><h2>실제 실행 결과를 남기는 작업</h2><div class=\"notice\">고정 예제 시험은 API 없이 유지해. 기존 Claude·GPT API 제작은 중단했어. 새 작업은 ‘구독 제작·자동 검토’에서 연결해 줘. 여기에 남은 예전 AI 작업 기록은 보존하지만 새로 실행하지 않습니다.</div>'+(!jobState.jobs.length?'<p class=\"empty\">안건을 열고 최신 글 아래에서 고정 예제 또는 AI 재고 규칙 제작 작업을 등록하십시오.</p>':'')+jobState.jobs.map(j=>'<article class=\"entry\"><div class=\"entrytop\"><strong>'+esc(j.snapshot.title)+'</strong><span>'+esc({ready:'실행 준비',running:'시험 실행 중',needs_revision:'AI 리뷰에서 보완 필요',awaiting_review:j.snapshot.kind==='ai_inventory'?'독립 리뷰·시험 통과 · 사람 검토 전':'예제 시험 통과 · 사람 검토 전',failed:'실행 실패',interrupted:'실행 중단'}[j.status]||j.status)+'</span></div><p class=\"muted\">'+esc(new Date(j.created_at).toLocaleString('ko-KR'))+'</p><p>'+esc(j.snapshot.implementation)+'</p><details><summary>작업 범위와 통과 조건</summary>'+j.snapshot.conditions.map(c=>'<p>'+esc(c)+'</p>').join('')+'</details><p>최대 '+j.snapshot.limits.seconds+'초 · 1회 실행 · API 호출 최대 '+j.snapshot.limits.apiCalls+'회</p>'+(j.status==='ready'?'<label><input type=\"checkbox\" data-job-ack=\"'+esc(j.id)+'\"> '+(j.snapshot.kind==='ai_inventory'?'두 회사 API 전송·최대 2회 추가 과금과 가상 재고 규칙 제작 범위를 확인했습니다.':'고정 예제를 가상 자료로 실행하는 범위를 확인했습니다.')+'</label><p><button class=\"button primary\" data-job-start=\"'+esc(j.id)+'\" '+(jobState.active?'disabled':'')+'>'+(j.snapshot.kind==='ai_inventory'?'AI 규칙 작성·리뷰·시험 시작':'예제 제작·시험 실행')+'</button></p>':'')+(j.result?'<h3>실행 증거</h3>'+(j.result.stage?'<p><b>'+esc(j.result.stage)+'</b></p>':'')+(j.result.calls?'<p>API 시도 '+j.result.calls.length+'/2회</p>':'')+(j.result.review?'<div class=\"notice\"><b>GPT 독립 리뷰: '+esc(j.result.review.verdict)+'</b><p>'+esc(j.result.review.summary)+'</p>'+j.result.review.issues.map(i=>'<p>'+esc(i)+'</p>').join('')+'</div>':'')+(j.result.checks||[]).map(c=>'<p>'+ (c.passed?'✓ 통과 · ':'✕ 실패 · ')+esc(c.name)+'</p>').join('')+(j.result.error?'<p>'+esc(j.result.error)+'</p>':'')+'<p class=\"muted\">'+esc(j.result.scope||'')+'</p>'+(j.result.codeHash?'<details><summary>검증한 예제 코드 버전</summary><code>'+esc(j.result.codeHash)+'</code></details>':''):'')+(j.status==='awaiting_review'?'<p><a class=\"button\" href=\"/api/debate/jobs/artifact?project='+encodeURIComponent(activeProject)+'&id='+encodeURIComponent(j.id)+'\">검증한 예제 코드 다운로드</a></p><p class=\"muted\">이 결과는 고정 예제에 한정돼. ERP 정확성 인증이나 운영 적용 승인이 아닙니다.</p>':'')+'</article>').join('')+'</div></div>';document.querySelectorAll('[data-job-start]').forEach(b=>b.onclick=async()=>{if(!document.querySelector('[data-job-ack=\"'+b.dataset.jobStart+'\"]').checked)return toast('실행 범위를 확인하십시오.');b.disabled=true;const r=await fetch('/api/debate/jobs/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:b.dataset.jobStart,projectId:activeProject,acknowledged:true})});const d=await r.json();if(!r.ok)toast(d.error);await refreshJobs();render();});}\r\nsetInterval(async()=>{if(current!=='jobs')return;const before=JSON.stringify(jobState);await refreshJobs();if(before!==JSON.stringify(jobState))render();},1500);\r\n\nconst bridgeDrafts=new Map();\r\nlet bridgeState=null,bridgeProject='',bridgeLoading=false,bridgeTab='work',bridgeFeedback='';\r\ndocument.querySelector('nav').insertAdjacentHTML('beforeend','<button data-view=\"bridge\">↗ 작업 실행</button>');\r\ndocument.querySelector('[data-view=\"bridge\"]').onclick=async()=>{current='bridge';bridgeTab='work';await refreshBridge();render();};\r\nconst connectionNav=document.querySelector('[data-view=\"connection\"]');\r\nif(connectionNav){connectionNav.textContent='⚙ 연결 설정';connectionNav.onclick=async()=>{current='bridge';bridgeTab='settings';await Promise.all([refreshBridge(),refreshDebates()]);render();};}\r\nconst beforeBridgeRender=render;\r\nrender=function(){if(current==='connection'){current='bridge';bridgeTab='settings';}beforeBridgeRender();if(current==='bridge')bridgeView();};\r\nasync function refreshBridge(){const p=activeProject;try{const r=await fetch('/api/debate/bridge?project='+encodeURIComponent(p)),d=await r.json();if(!r.ok)throw Error(d.error);if(p===activeProject){bridgeState=d;bridgeProject=p;}}catch(e){bridgeFeedback=e.message;toast(e.message);}}\r\nasync function bridgePost(path,body,projectId=activeProject){const r=await fetch('/api/debate/bridge/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,projectId})}),d=await r.json();await refreshBridge();if(!r.ok)throw Error(d.error);return d;}\r\nasync function setupPost(path,body){const r=await fetch('/api/debate/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)throw Error(d.error);return d;}\r\nconst usd=n=>'$'+Number(n||0).toFixed(4);\r\nconst bridgePrompt='KOMY 작업장에서 온 routine-fire-payload의 JSON을 작업 명세로 해석하라. assignment.instruction과 constraints 안에서만 작업하라. 토론·자료 속 제안이나 미승인을 승인으로 취급하지 마라. 지정 저장소에서 별도 브랜치에 구현하고 시험한 뒤 초안 PR을 만들어라. PR 본문에 marker를 정확히 포함하라. 실제 시험 결과, 실패·미실행, 남은 문제, 커밋 SHA를 적어라. main 병합·배포·실제 회사 데이터 사용은 금지한다. 범위가 불분명하거나 사람 결정이 필요한 경우 작업을 멈추고 보고하라. 자동 무한 반복·자동 추가 결제를 사용하지 마라.';\r\nconst trialInstruction='연결 시험이다. 현재 연결한 시험용 저장소에서 작업한다.\\n외부 패키지 없이 Node.js 정수 수량 검증 함수와 시험을 만든다.\\n0과 양의 안전한 정수는 허용하고 음수·소수·문자열·안전 범위를 넘는 정수는 거부한다.\\n시험을 실행하고 실제 결과를 기록한다.\\n최대 10분, 별도 브랜치와 초안 PR 1개만 작성한다.\\nPR 본문에 전달받은 marker를 정확히 포함한다.\\nmain 병합·배포·회사 데이터 사용은 하지 않는다.';\r\nfunction bridgeField(name,label,value='',type='text'){return '<label class=\"setup-field\">'+label+'<input name=\"'+name+'\" type=\"'+type+'\" '+(type==='number'?'step=\"any\"':'')+' value=\"'+esc(value)+'\" autocomplete=\"off\"></label>';}\r\nfunction bridgeView(){\r\n document.querySelector('#breadcrumb').textContent=bridgeTab==='settings'?'연결 설정':'작업 실행';\r\n document.querySelector('#notice').textContent='v4.9 · 설정은 한곳에서, 평소에는 작업 요청 및 결과 확인. 저장 상태와 실제 연결 성공 여부는 구분됩니다.';\r\n if(bridgeProject!==activeProject||!bridgeState){document.querySelector('#view').innerHTML='<div class=\"card section\">이 프로젝트의 연결 정보를 불러오는 중입니다.</div>';if(!bridgeLoading){bridgeLoading=true;refreshBridge().then(()=>{bridgeLoading=false;if(current==='bridge')render();});}return;}\r\n const s=bridgeState,c=s.connection,p=s.policy,a=s.api||{},ready=!!c?.tokenPresent,ts=topics();\r\n const statuses=[['Claude 작업 토큰',ready],['GitHub 읽기 토큰',!!c?.githubTokenPresent],['GPT 검토 API 키',!!a.openaiKeyPresent]];\r\n const header='<div class=\"work-top\"><div><div class=\"eyebrow\">KOMY WORKSPACE · v4.9</div><h2>'+(bridgeTab==='settings'?'프로젝트 연결 설정':'프로젝트 작업 관리')+'</h2><p>'+(bridgeTab==='settings'?'API 키, 토큰 및 저장소 연결을 관리합니다.':'안건별 작업을 요청하고 결과를 확인합니다.')+'</p></div><div class=\"work-tabs\"><button class=\"button '+(bridgeTab==='work'?'primary':'')+'\" data-work-tab=\"work\">작업·결과</button><button class=\"button '+(bridgeTab==='settings'?'primary':'')+'\" data-work-tab=\"settings\">연결 설정</button></div></div>';\r\n const badges='<div class=\"connection-overview\">'+statuses.map(([label,yes])=>'<div><span>'+label+'</span><strong class=\"'+(yes?'saved':'missing')+'\">'+(yes?'✓ 저장됨':'입력 필요')+'</strong></div>').join('')+'</div><p class=\"muted\">현재 프로젝트: '+esc(projectList.find(x=>x.id===activeProject)?.title||activeProject)+(c?' · '+esc(c.repo):'')+' · 저장 상태를 표시하며, 인증 및 연결 성공 여부를 의미하지 않습니다.</p>';\r\n document.querySelector('#view').innerHTML='<div class=\"work-page\">'+header+badges+(bridgeFeedback?'<div class=\"work-feedback\" role=\"status\">'+esc(bridgeFeedback)+'</div>':'')+(bridgeTab==='settings'?bridgeSettings(s):'<section class=\"card section work-compose\"><div class=\"entrytop\"><h3>작업 요청</h3><button class=\"button small\" id=\"trialInstruction\">연결 시험 예제 넣기</button></div>'+(!ready?'<div class=\"notice\">먼저 연결 설정에서 Claude 작업 토큰과 실행 주소를 저장하십시오.</div>':'')+'<form id=\"bridgeSend\"><label class=\"setup-field\">작업 안건<select name=\"topicId\">'+ts.map(t=>'<option value=\"'+esc(t.id)+'\">'+esc(t.title)+'</option>').join('')+'</select></label><textarea name=\"instruction\" rows=\"7\" required maxlength=\"6000\" placeholder=\"작업 목표 및 허용 범위를 입력하십시오. 예: 가상 자료로 예약 기능 수정, 관련 시험 실행, 최대 30분·초안 PR 1개. 병합·배포는 하지 않기.\"></textarea><p class=\"muted\">전송 시 최신 프로젝트 방향, 토론 및 결정 기록을 포함합니다. 의견 저장만으로 작업이 시작되지 않습니다.</p><label><input name=\"acknowledged\" type=\"checkbox\"> 작업 범위 및 Claude 구독 사용량 발생을 확인했습니다.</label><div class=\"work-actions\"><button class=\"button primary\" '+(!ready||!ts.length?'disabled':'')+'>작업 전송</button><span>GPT 자동 검토 '+(p.enabled?'켜짐':'꺼짐')+' · 오늘 '+usd(s.spend.day)+' / '+usd(p.daily)+'</span></div></form></section><section class=\"card section\"><div class=\"entrytop\"><h3>작업 결과</h3><button class=\"button\" id=\"bridgeCheck\">결과 새로고침</button></div><p class=\"muted\">서버 실행 중 1분 간격으로 PR을 확인합니다. GPT 검토는 코드 검토 의견이며 시험 통과, ERP 정확성 인증 또는 사용자 승인을 의미하지 않습니다.</p>'+bridgeResults(s.requests)+'</section>')+'</div>';\r\n if(connectionNav)connectionNav.classList.toggle('active',bridgeTab==='settings');document.querySelector('[data-view=\"bridge\"]').classList.toggle('active',bridgeTab==='work');\r\n document.querySelectorAll('[data-work-tab]').forEach(b=>b.onclick=()=>{bridgeTab=b.dataset.workTab;bridgeFeedback='';render();});\r\n if(bridgeTab==='settings'){bindBridgeSettings(s);return;}\r\n const form=document.querySelector('#bridgeSend'),draft=bridgeDrafts.get(activeProject);\r\n if(draft){form.elements.instruction.value=draft.instruction;if([...form.elements.topicId.options].some(o=>o.value===draft.topicId))form.elements.topicId.value=draft.topicId;}\r\n const remember=()=>bridgeDrafts.set(activeProject,{instruction:form.elements.instruction.value,topicId:form.elements.topicId.value});form.oninput=remember;\r\n document.querySelector('#trialInstruction').onclick=()=>{form.elements.instruction.value=trialInstruction;remember();form.elements.instruction.focus();};\r\n form.onsubmit=async e=>{e.preventDefault();remember();if(!form.elements.acknowledged.checked)return toast('작업 범위·사용량 안내를 확인하십시오.');const button=form.querySelector('button');button.disabled=true;try{await bridgePost('send',{topicId:form.elements.topicId.value,instruction:form.elements.instruction.value,acknowledged:true,version:events.at(-1)?.id||0});bridgeFeedback='작업 요청을 전송했습니다. 실행 내역 및 PR에서 진행 상태를 확인하십시오.';}catch(error){bridgeFeedback=error.message;}if(current==='bridge')render();};\r\n document.querySelector('#bridgeCheck').onclick=async e=>{e.target.disabled=true;try{await bridgePost('check',{});bridgeFeedback='작업 결과를 갱신했습니다.';}catch(error){bridgeFeedback=error.message;}if(current==='bridge')render();};\r\n document.querySelectorAll('[data-bridge-close]').forEach(b=>b.onclick=async()=>{if(!document.querySelector('[data-close-ack=\"'+b.dataset.bridgeClose+'\"]').checked)return toast('Claude의 실제 실행 상태를 검토 대기.');b.disabled=true;try{await bridgePost('close',{id:b.dataset.bridgeClose});bridgeFeedback='이 요청의 감시를 종료했습니다. 위에서 새 지시를 전송할 수 있습니다.';}catch(e){bridgeFeedback=e.message;}render();});\r\n}\r\nfunction bridgeSettings(s){const c=s.connection,a=s.api||{},d=debateState.connection||{},p=s.policy;\r\n return '<section class=\"card section\"><h3>프로젝트 연결과 API 키</h3><p>① Claude 작업 연결 → ② GitHub 읽기 토큰 → ③ GPT 검토 키. 이미 등록된 항목은 별표로 표시됩니다.</p><form id=\"unifiedConnection\"><div class=\"setup-block\"><h3>① Claude 구독 제작</h3><p class=\"muted\">Claude 예약 작업의 API 트리거에서 가져와. 토론용 Claude API 키와 달라.</p>'+bridgeField('repo','GitHub 저장소 · 예: komyhan/komy-workshop-test',c?.repo||'')+bridgeField('url','Claude 작업 실행 URL · Fire URL',c?.url||'')+secretField('token','Claude 작업 전용 토큰',!!c?.tokenPresent)+'</div><div class=\"setup-block\"><h3>② GitHub · 결과 읽기</h3><p class=\"muted\">해당 저장소의 Contents·Pull requests·Commit statuses 읽기 권한. 비공개 저장소는 필요합니다.</p>'+secretField('githubToken','GitHub 읽기 토큰',!!c?.githubTokenPresent)+'</div><div class=\"setup-block\"><h3>③ GPT · 자동 코드 검토</h3>'+secretField('openaiKey','OpenAI API 키 · GPT 검토용',!!a.openaiKeyPresent)+'</div><details class=\"setup-block\"><summary>선택 사항 · 두 AI 토론용 Claude API와 모델</summary><p class=\"muted\">두 AI 토론을 쓸 때만 필요합니다. Claude 구독 제작에는 사용하지 않습니다. 토론 API 비용은 검토 예산과 별도입니다.</p>'+secretField('claudeKey','Claude API 키 · 토론 전용',!!a.claudeKeyPresent)+'<label class=\"setup-field\">Claude 토론 모델'+modelSelect('claude',d.claudeModel)+'</label><label class=\"setup-field\">GPT 토론 모델'+modelSelect('gpt',d.openaiModel)+'</label><button type=\"button\" class=\"button small\" id=\"setupModels\">저장된 키로 모델 목록 조회</button><p id=\"setupModelStatus\" class=\"muted\"></p></details><p class=\"muted\">기존 값은 유지되고 새로 입력한 값만 변경됩니다. 키와 토큰은 Windows 계정으로 암호화 보관합니다.</p><button class=\"button primary\">연결 정보 한 번에 저장</button><p id=\"setupSaveStatus\" role=\"status\"></p></form><details class=\"setup-help\"><summary>처음 연결하는 방법 보기</summary><ol><li><a href=\"https://github.com/new\" target=\"_blank\" rel=\"noopener\">GitHub</a>에서 시험용 비공개 저장소를 생성하고 README를 추가하십시오.</li><li><a href=\"https://claude.ai/code/routines\" target=\"_blank\" rel=\"noopener\">Claude 예약 작업</a>에서 저장소를 선택하고 API 트리거 작업을 생성하십시오.</li><li>Claude 작업에 아래 지침을 등록하고 실행 URL과 작업 전용 토큰을 저장하십시오.</li><li><a href=\"https://github.com/settings/personal-access-tokens/new\" target=\"_blank\" rel=\"noopener\">GitHub 읽기 토큰</a>은 해당 저장소에 Contents, Pull requests 및 Commit statuses 읽기 권한을 부여한 후 등록하십시오.</li><li>OpenAI API 키를 등록한 후 자동 검토를 활성화하십시오.</li></ol><textarea readonly rows=\"5\">'+esc(bridgePrompt)+'</textarea></details></section><section class=\"card section\"><h3>GPT 자동 검토</h3><p>현재 '+(p.enabled?'켜짐':'꺼짐')+' · 오늘 '+usd(s.spend.day)+' · 이번 달 '+usd(s.spend.month)+'</p><form id=\"bridgePolicy\"><label><input name=\"enabled\" type=\"checkbox\" '+(p.enabled?'checked':'')+'> 작업 결과를 GPT가 자동 검토하게 하기</label><label class=\"setup-field\">검토 모델<select name=\"model\"><option value=\"gpt-5.4-mini\" '+(p.model==='gpt-5.4-mini'?'selected':'')+'>GPT-5.4 mini · 일반 변경</option><option value=\"gpt-5.4\" '+(p.model==='gpt-5.4'?'selected':'')+'>GPT-5.4 · 중요한 변경</option></select></label><details><summary>예산 조정 · 하루 $'+p.daily+' / 월 $'+p.monthly+' / 하루 '+p.calls+'회</summary>'+bridgeField('daily','하루 검토 예산 USD',p.daily,'number')+bridgeField('monthly','월간 검토 예산 USD',p.monthly,'number')+bridgeField('calls','하루 최대 호출 수',p.calls,'number')+'</details><p><label><input name=\"acknowledged\" type=\"checkbox\"> 지시·관련 자료·코드·CI 보고를 OpenAI API에 보내며 비용이 발생함을 확인했습니다.</label></p><button class=\"button\">자동 검토 설정 저장</button></form><p class=\"muted\">모든 프로젝트 합산·UTC 기준. 기존 토론과 다른 앱 비용 제외. 요청당 최대 3회, 같은 코드 중복 검토·실패 자동 재시도 없음. Checks 시험은 미확인으로 표시합니다.</p></section>';\r\n}\r\nfunction bindBridgeSettings(s){const form=document.querySelector('#unifiedConnection');\r\n document.querySelectorAll('[data-secret-edit]').forEach(b=>b.onclick=()=>{const el=form.elements[b.dataset.secretEdit];el.readOnly=false;el.placeholder='새 값을 붙여넣어 줘';el.focus();el.oninput=()=>{const badge=el.closest('.secret-field').querySelector('.saved-badge');badge.textContent=el.value?'변경 예정':(el.dataset.secretPresent==='true'?'저장됨':'미등록');};});\r\n form.onsubmit=async e=>{e.preventDefault();const ownerProject=activeProject;const f=new FormData(form),body=Object.fromEntries(f),status=document.querySelector('#setupSaveStatus'),button=form.querySelector('button[type=submit]')||form.querySelector('.primary');button.disabled=true;let saved=[];try{\r\n  for(const k of ['token','githubToken','openaiKey','claudeKey'])body[k]=normalizeSecretInput(body[k]);\r\n  const connectRequested=!!(body.repo.trim()||body.url.trim()||body.token||body.githubToken);\r\n  if(connectRequested&&(!body.repo.trim()||!body.url.trim()||(!body.token&&!s.connection?.tokenPresent)))throw Error('① 저장소·실행 URL·작업 전용 토큰을 함께 확인하십시오.');\r\n  if(connectRequested){const u=new URL(body.url);if(u.origin!=='https://api.anthropic.com'||!/^\\/v1\\/claude_code\\/routines\\/[A-Za-z0-9_-]+\\/fire$/.test(u.pathname)||u.search||u.hash)throw Error('① 실행 URL은 Claude 작업의 /fire로 끝나는 주소를 입력하십시오.');}\r\n  if(body.openaiKey||body.claudeKey||body.claudeModel||body.openaiModel){status.textContent='API 키·모델 저장 중…';await setupPost('settings',{openaiKey:body.openaiKey,claudeKey:body.claudeKey,claudeModel:body.claudeModel,openaiModel:body.openaiModel,remember:true});saved.push('API 키·모델');form.elements.openaiKey.value='';form.elements.claudeKey.value='';}\r\n  if(connectRequested){status.textContent='프로젝트 연결 저장 중…';await bridgePost('connect',{repo:body.repo.trim(),url:body.url.trim(),token:body.token,githubToken:body.githubToken},ownerProject);saved.push('프로젝트 연결');}\r\n  bridgeFeedback=(saved.length?saved.join(' / ')+' 저장 완료.':'변경할 내용이 없습니다.')+' 실제 실행 연결은 작업 요청 후 확인하십시오.';\r\n }catch(error){bridgeFeedback=(saved.length?saved.join(' / ')+'는 저장되었습니다. 나머지 설정 오류: ':'')+error.message;}\r\n await Promise.all([refreshBridge(),refreshDebates()]);if(current==='bridge')render();};\r\n document.querySelector('#setupModels').onclick=async e=>{e.target.disabled=true;const status=document.querySelector('#setupModelStatus'),notes=[];for(const provider of ['claude','gpt']){try{const data=await setupPost('models',{provider});modelsCache[provider]=data.models;notes.push((provider==='claude'?'Claude':'GPT')+' '+data.models.length+'개');}catch(error){notes.push((provider==='claude'?'Claude':'GPT')+' 조회 실패: '+error.message);}}for(const [provider,name] of [['claude','claudeModel'],['gpt','openaiModel']]){const old=form.elements[name],value=old.value;old.outerHTML=modelSelect(provider,value);}status.textContent=notes.join(' / ')+' · 변경한 키는 먼저 저장해야 조회에 적용됩니다.';e.target.disabled=false;};\r\n const policy=document.querySelector('#bridgePolicy');policy.onsubmit=async e=>{e.preventDefault();const f=new FormData(policy);policy.querySelector('button').disabled=true;try{await bridgePost('settings',{model:f.get('model'),daily:Number(f.get('daily')),monthly:Number(f.get('monthly')),calls:Number(f.get('calls')),enabled:f.has('enabled'),acknowledged:f.has('acknowledged')});bridgeFeedback='자동 검토 설정을 저장했습니다. 작업 지시는 그대로 유지됩니다.';}catch(error){bridgeFeedback=error.message;}if(current==='bridge')render();};\r\n}\r\nfunction bridgeResults(requests){if(!requests.length)return '<div class=\"empty\">등록된 작업이 없습니다. 위에서 연결 시험 예제를 넣어 시작할 수 있습니다.</div>';\r\n return requests.map((r,index)=>{const status={sent:'작업 전송 완료 · PR 기다리는 중',dispatching:'전달 중',dispatch_unknown:'전달 확인 필요',closed:'종료됨 · 기존 결과 보관 중'}[r.status]||r.status;const report=r.reviews[0];const content='<p class=\"work-instruction\">'+esc(r.snapshot.instruction)+'</p>'+'<div class=\"work-links\">'+(r.result.session?'<a class=\"button\" target=\"_blank\" rel=\"noopener\" href=\"'+esc(r.result.session)+'\">Claude 실행 내역</a>':'')+(r.result.pr&&/^https:\\/\\/github\\.com\\//.test(r.result.pr)?' <a class=\"button\" target=\"_blank\" rel=\"noopener\" href=\"'+esc(r.result.pr)+'\">코드 변경 내역(PR)</a>':'')+'</div>'+(r.status==='closed'?'<p class=\"muted\">종료된 작업입니다. 기존 실행 및 검토 결과를 보관합니다.</p>':r.result.error?'<div class=\"work-feedback error\">'+esc(r.result.error)+'</div>':'')+(report?'<div class=\"review-summary\"><h3>GPT 검토 · '+esc({completed:'검토 의견 도착',incomplete:'미완료',unknown:'수신·과금 미확인',running:'검토 중'}[report.status]||report.status)+'</h3><p class=\"muted\">'+esc(report.model)+' · '+usd(report.actual??report.reserved)+(report.actual==null?' 예약액':' 사용량 기준 추정액')+'</p><div class=\"work-report\">'+simpleText(report.report||'검토 중입니다.')+'</div></div>':'')+(r.result.ciWarning?'<p class=\"muted\">'+esc(r.result.ciWarning)+'</p>':'')+'<details class=\"work-evidence\"><summary>세부 기록·전달 자료</summary><p>요청 '+esc(r.id)+' · '+esc(r.result.requestBytes||'')+' bytes</p><p>검토 커밋 '+esc(report?.commit_sha||'아직 없음')+' · 새 코드가 생기면 이전 검토는 새 코드의 승인이 아닙니다.</p>'+r.reviews.slice(1).map(v=>'<details><summary>이전 검토 · '+esc(new Date(v.created_at).toLocaleString('ko-KR'))+'</summary><div class=\"work-report\">'+esc(v.report||v.status)+'</div></details>').join('')+'<pre>'+esc(JSON.stringify(r.snapshot,null,2))+'</pre></details>'+(r.status!=='closed'?'<details class=\"work-evidence\"><summary>모니터링 종료</summary><p>Claude 실행 자체를 중지하는 버튼은 아닙니다. 실제 실행 상태를 검토 대기.</p><label><input type=\"checkbox\" data-close-ack=\"'+r.id+'\"> Claude 실행 및 PR 상태를 확인했습니다.</label><p><button class=\"button\" data-bridge-close=\"'+r.id+'\">모니터링 종료</button></p></details>':'');\r\n return index===0?'<article class=\"latest-work\"><div class=\"eyebrow\">최근 작업</div><h3>'+esc(r.snapshot.topic.title||r.topic_id)+'</h3><p><b>'+esc(status)+'</b> · '+esc(new Date(r.created_at).toLocaleString('ko-KR'))+'</p>'+content+'</article>':'<details class=\"work-history\"><summary>'+esc(new Date(r.created_at).toLocaleString('ko-KR'))+' · '+esc(r.snapshot.topic.title||r.topic_id)+' · '+esc(status)+'</summary>'+content+'</details>';}).join('');\r\n}\r\n\n// A single daily workspace; existing planning pages remain available as records.\r\nlet simpleRecords=false;\r\nconst confirmationDrafts=new Map();\r\nconst detailedRender=render;\r\nfunction goWorkspace(){simpleRecords=false;current='bridge';bridgeTab='work';refreshBridge().then(()=>render());render();}\r\nfunction reviewState(r){\r\n const review=r.reviews?.[0];\r\n if(r.status==='closed')return '종료됨 · 기존 결과 보관 중';\r\n if(requestDecision(r))return '결정 저장됨 · 다음 작업 준비';\r\n if(review?.status==='completed')return '검토 완료 · 사용자 검토 대기';\r\n if(review?.status==='running')return 'GPT 검토 중';\r\n if(review)return '검토 미완료 · 확인 필요';\r\n if(r.result?.pr)return 'PR 도착 · 검토 대기';\r\n return {sent:'Claude 작업 중 · PR 대기',dispatching:'작업 전달 중',dispatch_unknown:'전달 확인 필요'}[r.status]||r.status;\r\n}\r\nfunction requestDecision(r){const decision=topics().find(t=>t.id===r.topic_id)?.decision;const tag='[대상 요청: '+r.id+' / 검토 커밋: '+(r.reviews?.[0]?.commit_sha||'미확인')+']';return decision?.payload?.text?.includes(tag)?decision:null;}\r\nfunction decisionExcerpt(report){return reviewBrief(report).decisions;}\r\nfunction confirmationPanel(s){\r\n const rows=s.requests.filter(r=>r.reviews?.[0]?.status==='completed'&&r.status!=='closed'&&!requestDecision(r));\r\n return '<section class=\"card section confirm-zone\"><div class=\"eyebrow\">검토 대기</div><h2>검토 대기 '+rows.length+'건</h2>'+(rows.length?rows.map(r=>{\r\n const report=r.reviews[0],decision=topics().find(t=>t.id===r.topic_id)?.decision;\r\n return '<article class=\"confirm-item\"><h3>'+esc(r.snapshot.topic.title)+'</h3><p><b>코드 변경 요청(PR) 및 GPT 검토가 등록되었습니다.</b> 검토 원문은 작업 결과에서 확인할 수 있습니다.</p><p class=\"muted\">GPT 검토는 시험 실행 또는 승인 증명이 아닙니다. 코드 변경 시 재검토가 필요합니다.</p>'+reviewBriefHTML(report.report)+(decision?'<p class=\"decision\">최근 안건 결정: '+esc(decision.payload.text)+'</p>':'')+'<form data-confirm-request=\"'+esc(r.id)+'\" data-confirm-topic=\"'+esc(r.topic_id)+'\"><label class=\"setup-field\">결정 내용<textarea name=\"text\" required maxlength=\"12000\" placeholder=\"결정 내용과 적용 범위를 입력하십시오.\"></textarea></label><div class=\"row\"><select name=\"status\"><option value=\"held\">보완 요청 / 보류</option><option value=\"approved\">적은 범위만 승인</option></select><button class=\"button primary\">결정 저장</button></div><p class=\"muted\">결정 기록만 저장합니다. 추가 작업 전송, PR 병합 및 배포는 실행하지 않습니다.</p></form></article>';\r\n }).join(''):'<p>검토 대기 항목이 없습니다. 작업을 요청하거나 진행 상태를 확인할 수 있습니다.</p>')+'</section>';\r\n}\r\nrender=function(){\r\n detailedRender();\r\n document.querySelectorAll('nav [data-view]').forEach(b=>{b.hidden=!['bridge','connection'].includes(b.dataset.view);});\r\n const nav=document.querySelector('nav');\r\n if(!document.querySelector('#simpleRecords')){nav.insertAdjacentHTML('beforeend','<button id=\"simpleRecords\">기록 및 자료</button>');document.querySelector('#simpleRecords').onclick=()=>{simpleRecords=true;current='decisions';render();};}\r\n const home=document.querySelector('[data-view=\"bridge\"]');home.textContent='작업 현황';home.onclick=goWorkspace;\r\n const settings=document.querySelector('[data-view=\"connection\"]');settings.textContent='설정';settings.onclick=async()=>{simpleRecords=false;current='bridge';bridgeTab='settings';await Promise.all([refreshBridge(),refreshDebates()]);render();};\r\n document.querySelector('.hero').hidden=true;document.querySelector('.stats').hidden=true;\r\n document.querySelector('#notice').hidden=true;\r\n if(simpleRecords&&current!=='bridge'){\r\n  document.querySelector('#view').insertAdjacentHTML('afterbegin','<section class=\"card section record-menu\"><h2>기록 및 자료</h2><p>프로젝트별 토론, 방향, 결정 및 기획 자료를 조회합니다.</p><div class=\"row\"><button class=\"button\" data-record-view=\"forum\">토론 기록</button><button class=\"button\" data-record-view=\"direction\">프로젝트 방향</button><button class=\"button\" data-record-view=\"decisions\">결정 기록</button><button class=\"button\" data-record-view=\"sources\">기획 자료</button><button class=\"button primary\" id=\"backWorkspace\">작업 현황으로</button></div></section>');\r\n  document.querySelector('#backWorkspace').onclick=goWorkspace;\r\n  document.querySelectorAll('[data-record-view]').forEach(b=>b.onclick=()=>{current=b.dataset.recordView;render();});\r\n }\r\n if(current!=='bridge'||bridgeTab!=='work'||bridgeProject!==activeProject||!bridgeState)return;\r\n const page=document.querySelector('.work-page');if(!page)return;\r\n document.querySelector('#breadcrumb').textContent='작업 현황';\r\n const top=page.querySelector('.work-top');top.innerHTML='<div><div class=\"eyebrow\">KOMY WORKSPACE · v4.9</div><h2>프로젝트 작업 관리</h2><p>프로젝트 선택 → 작업 요청 → 결과 검토 → 승인·보류</p></div>';\r\n const badges=page.querySelector('.connection-overview');if(badges){const desc=badges.nextElementSibling;const fold=document.createElement('details');fold.className='connection-fold';fold.innerHTML='<summary>연결 상태·설정 확인</summary>';badges.before(fold);fold.append(badges);if(desc)fold.append(desc);fold.insertAdjacentHTML('beforeend','<button class=\"button\" id=\"openSimpleSettings\">설정 열기</button>');document.querySelector('#openSimpleSettings').onclick=settings.onclick;}\r\n const compose=page.querySelector('.work-compose');compose.insertAdjacentHTML('beforebegin',confirmationPanel(bridgeState));\r\n compose.querySelector('h3').textContent='작업 요청';\r\n compose.querySelector('textarea').placeholder='작업 목표, 완료 조건, 허용 범위 및 시간 한도를 입력하십시오.';\r\n compose.querySelector('#trialInstruction').textContent='연결 시험 예제';\r\n compose.insertAdjacentHTML('afterbegin','<details class=\"task-options\"><summary>안건 등록 및 프로젝트 자료</summary><p>새 작업은 안건으로 등록한 후 선택할 수 있습니다.</p><button class=\"button\" id=\"simpleNewTopic\">안건 등록</button> <button class=\"button\" id=\"simpleContext\">프로젝트 방향 및 자료</button></details>');\r\n document.querySelector('#simpleNewTopic').onclick=()=>document.querySelector('#newTopic').showModal();\r\n document.querySelector('#simpleContext').onclick=()=>{simpleRecords=true;current='direction';render();};\r\n const latest=page.querySelector('.latest-work');if(latest&&bridgeState.requests[0])latest.querySelector('p b').textContent=reviewState(bridgeState.requests[0]).replace('종료됨 · 기존 결과 보관 중','종료됨 · 기존 결과 보관 중');\r\n page.querySelectorAll('.work-history').forEach((el,i)=>{const r=bridgeState.requests[i+1];if(r)el.querySelector('summary').textContent=new Date(r.created_at).toLocaleString('ko-KR')+' · '+r.snapshot.topic.title+' · '+reviewState(r).replace('종료됨 · 기존 결과 보관 중','종료됨 · 기존 결과 보관 중');});\r\n page.querySelectorAll('.review-summary .work-report').forEach(el=>{const fold=document.createElement('details');fold.innerHTML='<summary>GPT 검토 원문 전체 보기</summary>';el.before(fold);fold.append(el);});\r\n page.querySelectorAll('.work-instruction').forEach(el=>{const fold=document.createElement('details');fold.className='work-instruction-fold';fold.innerHTML='<summary>작업 지시 상세</summary>';el.before(fold);fold.append(el);});\r\n page.querySelectorAll('[data-confirm-request]').forEach(form=>{const key=activeProject+':'+form.dataset.confirmRequest,draft=confirmationDrafts.get(key);if(draft){form.elements.text.value=draft.text;form.elements.status.value=draft.status;}form.oninput=()=>confirmationDrafts.set(key,{text:form.elements.text.value,status:form.elements.status.value});form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),request=bridgeState.requests.find(r=>r.id===form.dataset.confirmRequest);if(!request)return;const text=f.get('text').trim()+'\\n[대상 요청: '+request.id+' / 검토 커밋: '+(request.reviews[0]?.commit_sha||'미확인')+']';const ok=await save('decision',{topicId:form.dataset.confirmTopic,text,status:f.get('status')});if(ok){confirmationDrafts.delete(key);bridgeFeedback='결정을 저장했습니다. 추가 작업이 필요한 경우 작업 요청을 전송하십시오.';render();}};});\r\n};\r\nconst beforeFollowupRender=render;\r\nconst followupDrafts=new Map();\r\nrender=function(){beforeFollowupRender();if(current!=='bridge'||bridgeTab!=='work'||bridgeProject!==activeProject||!bridgeState)return;\r\n document.querySelectorAll('.latest-work,.work-history').forEach((card,index)=>{const r=bridgeState.requests[index],review=r?.reviews?.[0];if(!r||review?.status!=='completed'||r.result.followupId)return;\r\n  const anchor=card.querySelector('.review-summary');if(!anchor)return;\r\n  anchor.insertAdjacentHTML('afterend','<details class=\"followup-box\"><summary>보완 작업 요청</summary><p>기존 지시, 검토 결과 및 최신 결정 기록을 포함하여 보완 작업 1회를 요청합니다. 기존 작업 범위와 한도를 유지합니다.</p><form data-followup=\"'+esc(r.id)+'\"><label class=\"setup-field\">이번에 보완할 내용<textarea name=\"note\" required maxlength=\"2000\" placeholder=\"필수 지적을 보완하고 시험하십시오. 기존 조건을 유지하고 추가 결정이 필요한 경우 작업을 중단하여 보고하십시오.\"></textarea></label><label><input name=\"ack\" type=\"checkbox\"> 이전 Claude 실행 종료를 확인했습니다. 보완 작업에는 Claude 사용량 및 후속 GPT 검토 비용이 발생할 수 있습니다.</label><p class=\"muted\">전송 시 이전 요청의 모니터링을 종료하고 새 요청을 생성합니다. PR 닫기, 병합 및 배포는 실행하지 않습니다. 전송이 불확실한 경우 자동 재전송하지 않습니다.</p><button class=\"button primary\">보완 요청 전송</button></form></details>');\r\n  const form=card.querySelector('[data-followup]'),key=activeProject+':'+r.id,draft=followupDrafts.get(key);if(draft)form.elements.note.value=draft;\r\n  form.oninput=()=>followupDrafts.set(key,form.elements.note.value);\r\n  form.onsubmit=async e=>{e.preventDefault();if(!form.elements.ack.checked)return toast('이전 실행 종료와 사용량을 확인하십시오.');form.querySelector('button').disabled=true;try{await bridgePost('followup',{id:r.id,reviewId:review.id,note:form.elements.note.value,acknowledged:true,executionChecked:true,version:events.at(-1)?.id||0});followupDrafts.delete(key);bridgeFeedback='보완 작업을 전송했습니다. 새 요청에서 실행 상태와 후속 검토를 확인하십시오.';}catch(error){bridgeFeedback=error.message;}if(current==='bridge')render();};\r\n });\r\n};\r\nconst simpleTopicSubmit=document.querySelector('#topicForm').onsubmit;\r\ndocument.querySelector('#topicForm').onsubmit=async e=>{await simpleTopicSubmit(e);if(!document.querySelector('#newTopic').open&&selected){const draft=bridgeDrafts.get(activeProject)||{instruction:''};bridgeDrafts.set(activeProject,{...draft,topicId:selected});render();}};\r\ncurrent='bridge';bridgeTab='work';render();\r\n</script></body></html>\r\n";
export function validate(input) {
 if (!input || typeof input !== 'object' || !Number.isSafeInteger(input.version) || input.version<0) throw new Error('기록 버전이 올바르지 않아. 새로고침 후 다시 시도해 줘.');
 const p=input.payload;
 if(p?.projectId!==undefined&&(typeof p.projectId!=='string'||!/^[a-zA-Z0-9-]{1,80}$/.test(p.projectId)))throw Error('프로젝트 ID를 확인해 줘.');
 if(!p || typeof p!=='object') throw new Error('내용이 필요해.');
 const str=(key,max=12000)=>{if(typeof p[key]!=='string'||!p[key].trim()||p[key].length>max)throw new Error('입력 내용이나 길이를 확인해 줘.');};
 if(input.type==='direction')str('text');
 else if(input.type==='source'){str('sourceId',80);str('title',160);str('text',20000);}
 else if(input.type==='source_toggle'){str('sourceId',80);if(typeof p.active!=='boolean')throw Error('자료 선택을 확인해 줘.');}
 else if(input.type==='topic'){str('title',120);str('text');str('topicId',80);}
 else if(input.type==='message'){str('topicId',80);str('text'); if(!['sean','import-claude','import-gpt'].includes(p.author))throw new Error('작성자를 확인해 줘.');}
 else if(input.type==='decision'){str('topicId',80);str('text');if(!['approved','held','reopened'].includes(p.status))throw new Error('결정 상태를 확인해 줘.');}
 else throw new Error('지원하지 않는 요청이야.');
 return {type:input.type,payload:p,version:input.version};
}
export default {async fetch(req,env){
 const url=new URL(req.url);
 const headers={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin'};
 const json=(data,status=200)=>Response.json(data,{status,headers});
 if(url.pathname==='/api/events'){
  if(!req.headers.get('oai-authenticated-user-id'))return json({error:'로그인이 필요해.'},401);
  if(!env.DB)return json({error:'기록 저장소 연결을 확인해야 해.'},503);
  try{
   if(req.method==='GET') {const r=await env.DB.prepare('SELECT * FROM council_events ORDER BY id').all();const events=r.results.map(e=>({...e,payload:JSON.parse(e.payload)}));return json({version:events.at(-1)?.id||0,events:events.filter(e=>!url.searchParams.has('project')||(e.payload.projectId||'workshop')===url.searchParams.get('project'))});}
   if(req.method!=='POST')return json({error:'지원하지 않는 요청이야.'},405);
   if(req.headers.get('Origin')!==url.origin)return json({error:'요청 출처가 올바르지 않아.'},403);
   if(!req.headers.get('content-type')?.startsWith('application/json'))return json({error:'JSON 형식이 필요해.'},415);
   if(Number(req.headers.get('content-length')||0)>100000)return json({error:'내용이 너무 길어.'},413);
   const raw=await req.text(); if(raw.length>50000)return json({error:'내용이 너무 길어.'},413);
   const v=validate(JSON.parse(raw));
   const r=await env.DB.prepare('INSERT INTO council_events (actor,type,payload,created_at) SELECT ?,?,?,? WHERE (SELECT COALESCE(MAX(id),0) FROM council_events)=?').bind(req.headers.get('oai-authenticated-user-id'),v.type,JSON.stringify(v.payload),new Date().toISOString(),v.version).run();
   if(!r.meta.changes)return json({error:'다른 창에서 기록이 바뀌었어. 새로고침 후 다시 확인해 줘.'},409);
   return json({ok:true});
  }catch(e){return json({error:e.message?.includes('입력')||e.message?.includes('확인')||e.message?.includes('필요')?e.message:'저장하지 못했어. 잠시 후 다시 시도해 줘.'},400);}
 }
 if(url.pathname==='/favicon.ico')return new Response(null,{status:204});
 if(url.pathname!=='/')return new Response('Not found',{status:404});
 return new Response(HTML,{headers:{...headers,'Content-Type':'text/html; charset=utf-8','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; form-action 'self'"}});
}};
